                    chapterId = chapterId,
                    pageIndex = pageIndex,
                    ocrModel = prefs.ocrModel().get(),
                    imageWidth = ocrBitmap.width,
                    imageHeight = ocrBitmap.height,
                    regions = emptyList(),
