/**
 * Moves to the previous page.
 */
open fun moveToPrevious() {
    if (tryAdvancePanelBackward()) return
    logcat(LogPriority.VERBOSE) { "Panel nav viewer fallback moveToPrevious -> page" }
    moveLeft()
