 class MangaScreenModel(
     private val context: Context,
     private val lifecycle: Lifecycle,
     private val mangaId: Long,
     private val isFromSource: Boolean,
     private val libraryPreferences: LibraryPreferences = Injekt.get(),
     trackPreferences: TrackPreferences = Injekt.get(),
     readerPreferences: ReaderPreferences = Injekt.get(),
     private val trackerManager: TrackerManager = Injekt.get(),
     private val trackChapter: TrackChapter = Injekt.get(),
     private val downloadManager: DownloadManager = Injekt.get(),
     private val downloadCache: DownloadCache = Injekt.get(),
     private val getMangaAndChapters: GetMangaWithChapters = Injekt.get(),
     private val getDuplicateLibraryManga: GetDuplicateLibraryManga = Injekt.get(),
     private val getAvailableScanlators: GetAvailableScanlators = Injekt.get(),
     private val getExcludedScanlators: GetExcludedScanlators = Injekt.get(),
     private val setExcludedScanlators: SetExcludedScanlators = Injekt.get(),
     private val setMangaChapterFlags: SetMangaChapterFlags = Injekt.get(),
     private val setMangaDefaultChapterFlags: SetMangaDefaultChapterFlags = Injekt.get(),
     private val setReadStatus: SetReadStatus = Injekt.get(),
     private val updateChapter: UpdateChapter = Injekt.get(),
     private val updateManga: UpdateManga = Injekt.get(),
     private val getCategories: GetCategories = Injekt.get(),
     private val getTracks: GetTracks = Injekt.get(),
     private val addTracks: AddTracks = Injekt.get(),
     private val setMangaCategories: SetMangaCategories = Injekt.get(),
     private val mangaRepository: MangaRepository = Injekt.get(),
     private val filterChaptersForDownload: FilterChaptersForDownload = Injekt.get(),
     private val getCachedChapterIdsOcr: GetCachedChapterIdsOcr = Injekt.get(),
     private val ocrScanManager: OcrScanManager = Injekt.get(),
     private val updateMangaFromRemote: UpdateMangaFromRemote = Injekt.get(),
     val snackbarHostState: SnackbarHostState = SnackbarHostState(),
 ) : StateScreenModel<MangaScreenModel.State>(State.Loading) {

     private val successState: State.Success?
         get() = state.value as? State.Success

     val manga: Manga?
         get() = successState?.manga

     val source: Source?
         get() = successState?.source

     private val isFavorited: Boolean
         get() = manga?.favorite ?: false

     private val allChapters: List<ChapterList.Item>?
         get() = successState?.chapters

     private val filteredChapters: List<ChapterList.Item>?
         get() = successState?.processedChapters

     val chapterSwipeStartAction = libraryPreferences.swipeToEndAction.get()
     val chapterSwipeEndAction = libraryPreferences.swipeToStartAction.get()
     var autoTrackState = trackPreferences.autoUpdateTrackOnMarkRead.get()

     private val skipFiltered by readerPreferences.skipFiltered.asState(screenModelScope)

     val isUpdateIntervalEnabled =
         LibraryPreferences.MANGA_OUTSIDE_RELEASE_PERIOD in libraryPreferences.autoUpdateMangaRestrictions.get()

     private val selectedPositions: Array<Int> = arrayOf(-1, -1) // first and last selected index in list
     private val selectedChapterIds: HashSet<Long> = HashSet()

     /**
      * Helper function to update the UI state only if it's currently in success state
      */
     private inline fun updateSuccessState(func: (State.Success) -> State.Success) {
         mutableState.update {
             when (it) {
                 State.Loading -> it
                 is State.Success -> func(it)
             }
         }
     }

     init {
         screenModelScope.launchIO {
             combine(
                 getMangaAndChapters.subscribe(mangaId, applyScanlatorFilter = true).distinctUntilChanged(),
                 downloadCache.changes,
                 downloadManager.queueState,
             ) { mangaAndChapters, _, _ -> mangaAndChapters }
                 .flowWithLifecycle(lifecycle)
                 .collectLatest { (manga, chapters) ->
                     updateSuccessState {
                         it.copy(
                             manga = manga,
                             chapters = chapters.toChapterListItems(manga),
                         )
                     }
                 }
         }

         screenModelScope.launchIO {
             getExcludedScanlators.subscribe(mangaId)
                 .flowWithLifecycle(lifecycle)
                 .distinctUntilChanged()
                 .collectLatest { excludedScanlators ->
                     updateSuccessState {
                         it.copy(excludedScanlators = excludedScanlators)
                     }
                 }
         }

         screenModelScope.launchIO {
             getAvailableScanlators.subscribe(mangaId)
                 .flowWithLifecycle(lifecycle)
                 .distinctUntilChanged()
                 .collectLatest { availableScanlators ->
                     updateSuccessState {
                         it.copy(availableScanlators = availableScanlators)
                     }
                 }
         }

         observeDownloads()
         observeScanCache()

         screenModelScope.launchIO {
             val manga = getMangaAndChapters.awaitManga(mangaId)
             val chapters = getMangaAndChapters.awaitChapters(mangaId, applyScanlatorFilter = true)
                 .toChapterListItems(manga)

             if (!manga.favorite) {
                 setMangaDefaultChapterFlags.await(manga)
             }

             val needRefreshInfo = !manga.initialized
             val needRefreshChapter = chapters.isEmpty()

             // Show what we have earlier
             mutableState.update {
                 State.Success(
                     manga = manga,
                     source = Injekt.get<SourceManager>().getOrStub(manga.source),
                     isFromSource = isFromSource,
                     chapters = chapters,
                     availableScanlators = getAvailableScanlators.await(mangaId),
                     excludedScanlators = getExcludedScanlators.await(mangaId),
                     isRefreshingData = needRefreshInfo || needRefreshChapter,
                     dialog = null,
                     hideMissingChapters = libraryPreferences.hideMissingChapters.get(),
                 )
             }

             // Start observe tracking since it only needs mangaId
             observeTrackers()

             // Fetch info-chapters when needed
             if ((needRefreshInfo || needRefreshChapter) && screenModelScope.isActive) {
                 fetchAllFromSource(
                     manualFetch = false,
                     fetchDetails = needRefreshInfo,
                     fetchChapters = needRefreshChapter,
                 )
             }

             // Initial loading finished
             updateSuccessState { it.copy(isRefreshingData = false) }
         }
     }

     fun fetchAllFromSource(manualFetch: Boolean = true) {
         screenModelScope.launch {
             updateSuccessState { it.copy(isRefreshingData = true) }
             fetchAllFromSource(
                 manualFetch = manualFetch,
                 fetchDetails = true,
                 fetchChapters = true,
             )
             updateSuccessState { it.copy(isRefreshingData = false) }
         }
     }

     private suspend fun fetchAllFromSource(
         manualFetch: Boolean,
         fetchDetails: Boolean,
         fetchChapters: Boolean,
     ) {
         val state = successState ?: return
         try {
             withUIContext {
                 val update = updateMangaFromRemote(
                     source = state.source,
                     manga = state.manga,
                     fetchDetails = fetchDetails,
                     fetchChapters = fetchChapters,
                     manualFetch = manualFetch,
                 )
                     .getOrThrow()

                 if (manualFetch) {
                     downloadNewChapters(update.newChapters)
                 }
             }
         } catch (_: CancellationException) {
             // ignore
         } catch (e: Exception) {
             val message = if (e is NoChaptersException) {
                 context.stringResource(MR.strings.no_chapters_error)
             } else {
                 logcat(LogPriority.ERROR, e)
                 with(context) { e.formattedMessage }
             }

             screenModelScope.launch {
                 // Повтор прямо в сообщении: строка с ошибкой исчезает через
                 // несколько секунд, а список глав остаётся пустым, и «0 глав»
                 // выглядит как правда. Кнопка «Повторить» возвращает список.
                 val retry = snackbarHostState.showSnackbar(
                     message = message,
                     actionLabel = "Повторить",
                     withDismissAction = true,
                 )
                 if (retry == SnackbarResult.ActionPerformed) {
                     fetchAllFromSource(manualFetch = true)
                 }
             }
         }
     }

     // Manga info - start

     fun toggleFavorite() {
         toggleFavorite(
             onRemoved = {
                 screenModelScope.launch {
                     if (!hasDownloads()) return@launch
                     val result = snackbarHostState.showSnackbar(
                         message = context.stringResource(MR.strings.delete_downloads_for_manga),
                         actionLabel = context.stringResource(MR.strings.action_delete),
                         withDismissAction = true,
                     )
                     if (result == SnackbarResult.ActionPerformed) {
                         deleteDownloads()
                     }
                 }
             },
         )
     }

     /**
      * Update favorite status of manga, (removes / adds) manga (to / from) library.
      */
     fun toggleFavorite(
         onRemoved: () -> Unit,
         checkDuplicate: Boolean = true,
     ) {
         val state = successState ?: return
         screenModelScope.launchIO {
             val manga = state.manga

             if (isFavorited) {
                 // Remove from library
                 if (updateManga.awaitUpdateFavorite(manga.id, false)) {
                     // Remove covers and update last modified in db
                     if (manga.removeCovers() != manga) {
                         updateManga.awaitUpdateCoverLastModified(manga.id)
                     }
                     withUIContext { onRemoved() }
                 }
             } else {
                 // Add to library
                 // First, check if duplicate exists if callback is provided
                 if (checkDuplicate) {
                     val duplicates = getDuplicateLibraryManga(manga)

                     if (duplicates.isNotEmpty()) {
                         updateSuccessState { it.copy(dialog = Dialog.DuplicateManga(manga, duplicates)) }
                         return@launchIO
                     }
                 }

                 // Now check if user previously set categories, when available
                 val categories = getCategories()
                 val defaultCategoryId = libraryPreferences.defaultCategory.get().toLong()
                 val defaultCategory = categories.find { it.id == defaultCategoryId }
                 when {
                     // Default category set
                     defaultCategory != null -> {
                         val result = updateManga.awaitUpdateFavorite(manga.id, true)
                         if (!result) return@launchIO
                         moveMangaToCategory(defaultCategory)
                     }

                     // Automatic 'Default' or no categories
                     defaultCategoryId == 0L || categories.isEmpty() -> {
                         val result = updateManga.awaitUpdateFavorite(manga.id, true)
                         if (!result) return@launchIO
                         moveMangaToCategory(null)
                     }

                     // Choose a category
                     else -> showChangeCategoryDialog()
                 }

                 // Finally match with enhanced tracking when available
                 addTracks.bindEnhancedTrackers(manga, state.source)
             }
         }
     }

     fun showChangeCategoryDialog() {
         val manga = successState?.manga ?: return
         screenModelScope.launch {
             val categories = getCategories()
             val selection = getMangaCategoryIds(manga)
             updateSuccessState { successState ->
                 successState.copy(
                     dialog = Dialog.ChangeCategory(
                         manga = manga,
                         initialSelection = categories.mapAsCheckboxState { it.id in selection },
                     ),
                 )
             }
         }
     }

     fun showSetFetchIntervalDialog() {
         val manga = successState?.manga ?: return
         updateSuccessState {
             it.copy(dialog = Dialog.SetFetchInterval(manga))
         }
     }

     fun setFetchInterval(manga: Manga, interval: Int) {
         screenModelScope.launchIO {
             if (
                 updateManga.awaitUpdateFetchInterval(
                     // Custom intervals are negative
                     manga.copy(fetchInterval = -interval),
                 )
             ) {
                 val updatedManga = mangaRepository.getMangaById(manga.id)
                 updateSuccessState { it.copy(manga = updatedManga) }
             }
         }
     }

     /**
      * Returns true if the manga has any downloads.
      */
     private fun hasDownloads(): Boolean {
         val manga = successState?.manga ?: return false
         return downloadManager.getDownloadCount(manga) > 0
     }

     /**
      * Deletes all the downloads for the manga.
      */
     private fun deleteDownloads() {
         val state = successState ?: return
         downloadManager.deleteManga(state.manga, state.source)
     }

     /**
      * Get user categories.
      *
      * @return List of categories, not including the default category
      */
     suspend fun getCategories(): List<Category> {
         return getCategories.await().filterNot { it.isSystemCategory }
     }

     /**
      * Gets the category id's the manga is in, if the manga is not in a category, returns the default id.
      *
      * @param manga the manga to get categories from.
      * @return Array of category ids the manga is in, if none returns default id
      */
     private suspend fun getMangaCategoryIds(manga: Manga): List<Long> {
         return getCategories.await(manga.id)
             .map { it.id }
     }

     fun moveMangaToCategoriesAndAddToLibrary(manga: Manga, categories: List<Long>) {
         moveMangaToCategory(categories)
         if (manga.favorite) return

         screenModelScope.launchIO {
             updateManga.awaitUpdateFavorite(manga.id, true)
         }
     }

     /**
      * Move the given manga to categories.
      *
      * @param categories the selected categories.
      */
     private fun moveMangaToCategories(categories: List<Category>) {
         val categoryIds = categories.map { it.id }
         moveMangaToCategory(categoryIds)
     }

     private fun moveMangaToCategory(categoryIds: List<Long>) {
         screenModelScope.launchIO {
             setMangaCategories.await(mangaId, categoryIds)
         }
     }

     /**
      * Move the given manga to the category.
      *
      * @param category the selected category, or null for default category.
      */
     private fun moveMangaToCategory(category: Category?) {
         moveMangaToCategories(listOfNotNull(category))
     }

     // Manga info - end

     // Chapters list - start

     private fun observeDownloads() {
         screenModelScope.launchIO {
             downloadManager.statusFlow()
                 .filter { it.manga.id == successState?.manga?.id }
                 .catch { error -> logcat(LogPriority.ERROR, error) }
                 .flowWithLifecycle(lifecycle)
                 .collect {
                     withUIContext {
                         updateDownloadState(it)
                     }
                 }
         }

         screenModelScope.launchIO {
             downloadManager.progressFlow()
                 .filter { it.manga.id == successState?.manga?.id }
                 .catch { error -> logcat(LogPriority.ERROR, error) }
                 .flowWithLifecycle(lifecycle)
                 .collect {
                     withUIContext {
                         updateDownloadState(it)
                     }
                 }
         }
     }

     private fun updateDownloadState(download: Download) {
         updateSuccessState { successState ->
             val modifiedIndex = successState.chapters.indexOfFirst { it.id == download.chapter.id }
             if (modifiedIndex < 0) return@updateSuccessState successState

             val newChapters = successState.chapters.toMutableList().apply {
                 val item = removeAt(modifiedIndex)
                     .copy(downloadState = download.status, downloadProgress = download.progress)
                 add(modifiedIndex, item)
             }
             successState.copy(chapters = newChapters)
         }
     }

     private fun observeScanCache() {
         screenModelScope.launchIO {
             ocrScanManager.cacheEvents
                 .flowWithLifecycle(lifecycle)
                 .collect { event ->
                     updateSuccessState { successState ->
                         val modifiedIndex = successState.chapters.indexOfFirst { it.id == event.chapterId }
                         if (modifiedIndex < 0) {
                             return@updateSuccessState successState
                         }

                         val newChapters = successState.chapters.toMutableList().apply {
                             val item = removeAt(modifiedIndex)
                                 .copy(hasScanResults = event.hasResults)
                             add(modifiedIndex, item)
                         }
                         successState.copy(chapters = newChapters)
                     }
                 }
         }
     }

     private suspend fun List<Chapter>.toChapterListItems(manga: Manga): List<ChapterList.Item> {
         val isLocal = manga.isLocal()
         val cachedChapterIds = getCachedChapterIdsOcr.await(mapNotNull(Chapter::id))
         return map { chapter ->
             val activeDownload = if (isLocal) {
                 null
             } else {
                 downloadManager.getQueuedDownloadOrNull(chapter.id)
             }
             val downloaded = if (isLocal) {
                 true
             } else {
                 downloadManager.isChapterDownloaded(
                     chapter.name,
                     chapter.scanlator,
                     chapter.url,
                     manga.title,
                     manga.source,
                 )
             }
             val downloadState = when {
                 activeDownload != null -> activeDownload.status
                 downloaded -> Download.State.DOWNLOADED
                 else -> Download.State.NOT_DOWNLOADED
             }

             ChapterList.Item(
                 chapter = chapter,
                 downloadState = downloadState,
                 downloadProgress = activeDownload?.progress ?: 0,
                 hasScanResults = chapter.id in cachedChapterIds,
                 selected = chapter.id in selectedChapterIds,
             )
         }
     }

     /**
      * @throws IllegalStateException if the swipe action is [LibraryPreferences.ChapterSwipeAction.Disabled]
      */
     fun chapterSwipe(chapterItem: ChapterList.Item, swipeAction: LibraryPreferences.ChapterSwipeAction) {
         screenModelScope.launch {
             executeChapterSwipeAction(chapterItem, swipeAction)
         }
     }

     /**
      * @throws IllegalStateException if the swipe action is [LibraryPreferences.ChapterSwipeAction.Disabled]
      */
     private fun executeChapterSwipeAction(
         chapterItem: ChapterList.Item,
         swipeAction: LibraryPreferences.ChapterSwipeAction,
     ) {
         val chapter = chapterItem.chapter
         when (swipeAction) {
             LibraryPreferences.ChapterSwipeAction.ToggleRead -> {
                 markChaptersRead(listOf(chapter), !chapter.read)
             }
             LibraryPreferences.ChapterSwipeAction.ToggleBookmark -> {
                 bookmarkChapters(listOf(chapter), !chapter.bookmark)
             }
             LibraryPreferences.ChapterSwipeAction.Download -> {
                 val downloadAction: ChapterDownloadAction = when (chapterItem.downloadState) {
                     Download.State.ERROR,
                     Download.State.NOT_DOWNLOADED,
                     -> ChapterDownloadAction.START_NOW
                     Download.State.QUEUE,
                     Download.State.DOWNLOADING,
                     -> ChapterDownloadAction.CANCEL
                     Download.State.DOWNLOADED -> ChapterDownloadAction.DELETE
                 }
                 runChapterDownloadActions(
                     items = listOf(chapterItem),
                     action = downloadAction,
                 )
             }
             LibraryPreferences.ChapterSwipeAction.Disabled -> throw IllegalStateException()
         }
     }

     /**
      * Returns the next unread chapter or null if everything is read.
      */
     fun getNextUnreadChapter(): Chapter? {
         val successState = successState ?: return null
         return successState.chapters.getNextUnread(successState.manga)
     }

     private fun getUnreadChapters(): List<Chapter> {
         val chapterItems = if (skipFiltered) filteredChapters.orEmpty() else allChapters.orEmpty()
         return chapterItems
             .filter { (chapter, dlStatus) -> !chapter.read && dlStatus == Download.State.NOT_DOWNLOADED }
             .map { it.chapter }
     }

     private fun getUnreadChaptersSorted(): List<Chapter> {
         val manga = successState?.manga ?: return emptyList()
         val chaptersSorted = getUnreadChapters().sortedWith(getChapterSort(manga))
         return if (manga.sortDescending()) chaptersSorted.reversed() else chaptersSorted
     }

     private fun getBookmarkedChapters(): List<Chapter> {
         val chapterItems = if (skipFiltered) filteredChapters.orEmpty() else allChapters.orEmpty()
         return chapterItems
             .filter { (chapter, dlStatus) -> chapter.bookmark && dlStatus == Download.State.NOT_DOWNLOADED }
             .map { it.chapter }
     }

     private fun startDownload(
         chapters: List<Chapter>,
         startNow: Boolean,
     ) {
         val successState = successState ?: return

         screenModelScope.launchNonCancellable {
             if (startNow) {
                 val chapterId = chapters.singleOrNull()?.id ?: return@launchNonCancellable
                 downloadManager.startDownloadNow(chapterId)
             } else {
                 downloadChapters(chapters)
             }

             if (!isFavorited && !successState.hasPromptedToAddBefore) {
                 updateSuccessState { state ->
                     state.copy(hasPromptedToAddBefore = true)
                 }
                 val result = snackbarHostState.showSnackbar(
                     message = context.stringResource(MR.strings.snack_add_to_library),
                     actionLabel = context.stringResource(MR.strings.action_add),
                     withDismissAction = true,
                 )
                 if (result == SnackbarResult.ActionPerformed && !isFavorited) {
                     toggleFavorite()
                 }
             }
         }
     }

     fun runChapterDownloadActions(
         items: List<ChapterList.Item>,
         action: ChapterDownloadAction,
     ) {
         when (action) {
             ChapterDownloadAction.START -> {
                 startDownload(items.map { it.chapter }, false)
                 if (items.any { it.downloadState == Download.State.ERROR }) {
                     downloadManager.startDownloads()
                 }
             }
             ChapterDownloadAction.START_NOW -> {
                 val chapter = items.singleOrNull()?.chapter ?: return
                 startDownload(listOf(chapter), true)
             }
             ChapterDownloadAction.CANCEL -> {
                 val chapterId = items.singleOrNull()?.id ?: return
                 cancelDownload(chapterId)
             }
             ChapterDownloadAction.DELETE -> {
                 deleteChapters(items.map { it.chapter })
             }
         }
     }

     fun runDownloadAction(action: DownloadAction) {
         val chaptersToDownload = when (action) {
             DownloadAction.NEXT_1_CHAPTER -> getUnreadChaptersSorted().take(1)
             DownloadAction.NEXT_5_CHAPTERS -> getUnreadChaptersSorted().take(5)
             DownloadAction.NEXT_10_CHAPTERS -> getUnreadChaptersSorted().take(10)
             DownloadAction.NEXT_25_CHAPTERS -> getUnreadChaptersSorted().take(25)
             DownloadAction.UNREAD_CHAPTERS -> getUnreadChapters()
             DownloadAction.BOOKMARKED_CHAPTERS -> getBookmarkedChapters()
         }
         if (chaptersToDownload.isNotEmpty()) {
             startDownload(chaptersToDownload, false)
         }
     }

     fun scanChapters(chapters: List<Chapter>) {
         if (chapters.isEmpty()) return
         toggleAllSelection(false)
         screenModelScope.launchIO {
             ocrScanManager.enqueue(chapters.mapNotNull(Chapter::id))
         }
     }

