     * `cropCurrentSelectionFrame` возвращал null, цикл тихо возвращался, и глава
     * «прочитана» на первой же странице. Теперь это просто повод подождать.
     */
    private suspend fun awaitFrameRendered(chapterRead: Boolean): Boolean {
        repeat(FRAME_RENDER_ATTEMPTS) {
            if (!coroutineContext.isActive) return false
            if (chapterRead && !autoReadActive) return false
            if (hasRenderedFrame()) return true
            delay(FRAME_RENDER_RETRY_MS)
        }
        return false
    }

    /** Есть ли что захватывать: вьювер уже показал хотя бы одну вьюху страницы. */
    private suspend fun hasRenderedFrame(): Boolean = withUIContext {
        val root = binding.root
        if (root.width <= 0 || root.height <= 0) return@withUIContext false
        viewModel.state.value.viewer
            ?.resolveSelectionCaptures(
                ReaderSelectionRegion(
                    screenRect = dialogRootRectToScreenRect(
                        android.graphics.RectF(0f, 0f, root.width.toFloat(), root.height.toFloat()),
                    ),
                ),
            )
            .orEmpty()
            .isNotEmpty()
    }

