 @Composable
 fun ReaderAiChatOverlay(
     context: Context,
     mangaId: Long?,
     mangaTitle: String,
     chapterTitle: String?,
     onClose: () -> Unit,
     onVoiceGender: String = "female",
     /**
      * Полная остановка по кнопке «Стоп»: прерывает ход агента и всё, что он
      * успел запустить. Без этого кнопка «Стоп» в меню читалки недоступна
      * именно тогда, когда она нужнее всего, — когда открыт чат.
      */
     onStopRequested: () -> Unit = {},
 ) {
     val history = remember { mutableStateListOf<Msg>() }
     var loading by remember { mutableStateOf(false) }
     var input by remember { mutableStateOf("") }
     var showClearConfirm by remember { mutableStateOf(false) }
     var showConsole by remember { mutableStateOf(false) }
     var attachedName by remember { mutableStateOf<String?>(null) }
     var attachedBytes by remember { mutableStateOf<ByteArray?>(null) }
     var activity by remember { mutableStateOf("") }
     var elapsed by remember { mutableStateOf(0L) }
     var backendLine by remember { mutableStateOf("") }
     var sessionLine by remember { mutableStateOf("") }
     // Как работаем с этой книгой: чат/отыгрыш, 18+, цензура. Заполняется
     // из файла книги и меняется чипами прямо в шапке. Ключ — mangaId, иначе
     // при переходе на другую книгу остались бы настройки предыдущей.
     var bookSettings by remember(mangaId) {
         mutableStateOf(BookKnowledge.profile(context, mangaId))
     }
     // У отыгрыша своя история: канал определяется режимом и объявлен здесь,
     // до лямбды отправки, которая его использует.
     val historyChannel = AiHistoryManager.channelOf(bookSettings.mode)
     // Растёт после каждого ответа: эффект ниже перечитывает сводку сессии.
     var sessionRefresh by remember { mutableStateOf(0) }

     // Вкладка чата: 0 — переписка, 1 — файлы workspace. Читатель искал файлы
     // в чате и в папке телефона: папки на Android 11+ приложение создать не
     // может, поэтому список файлов показываем прямо в чате.
     var tab by remember { mutableStateOf(0) }
     var filesRefresh by remember { mutableStateOf(0) }

     val listState = rememberLazyListState()
     val scope = rememberCoroutineScope()

     // Задача текущего хода: без ссылки её нечем прервать, а прерывать
     // читателю нужно — иначе ответ агента нельзя остановить.
     var runningJob by remember { mutableStateOf<kotlinx.coroutines.Job?>(null) }

     // Сообщение, отправленное «поверх» текущего хода. Раньше поле ввода
     // блокировалось на всё время работы агента, поэтому последовательно
     // спросить его было нельзя в принципе.
     var queuedMessage by remember { mutableStateOf<Pair<String, ByteArray?>?>(null) }

     val showToast: (String) -> Unit = { message -> context.toast(message) }
     val scrollTo: (Int) -> Unit = { index -> scope.launch { listState.animateScrollToItem(index) } }
     val setActivity: (String) -> Unit = { text ->
         scope.launch {
             activity = text
             elapsed = 0L
         }
     }

     LaunchedEffect(Unit) {
         val prefs = uy.kohesive.injekt.Injekt.get<mihon.domain.ocr.service.OcrPreferences>()
         // Снимок бэкенда читает сеть, каталоги моделей и сессии ранера — это
         // диск и binder, и на главном потоке (здесь это Main.immediate)
         // он подвешивал чат на открытии.
         val state = withContext(Dispatchers.IO) {
             eu.kanade.tachiyomi.data.ai.AiBackends.state(context, prefs)
         }
         val backend = eu.kanade.tachiyomi.data.ai.AiBackends.byId(prefs.aiBackend().get())
         val status = eu.kanade.tachiyomi.data.ai.AiBackends.statusOf(
             backend,
             state,
             prefs.aiProvider().get(),
         )
         val chatTarget = eu.kanade.tachiyomi.data.ai.AiModelRoles.chatTarget(
             chatBackend = prefs.aiBackend().get(),
             chatProvider = prefs.aiProvider().get(),
             chatModel = chatModelLabel(context, prefs),
         )
         val orchestrator = eu.kanade.tachiyomi.data.ai.AiModelRoles.orchestratorTarget(
             chatBackend = prefs.aiBackend().get(),
             chatProvider = prefs.aiProvider().get(),
             chatModel = chatTarget.model,
             orchestratorBackend = prefs.aiOrchestratorBackend().get(),
             orchestratorModel = prefs.aiOrchestratorModel().get(),
             backendState = state,
         )
         val ocrEngine = prefs.ocrModel().get()
         val autoRotate = prefs.aiAutoRotate().get()
         val lines = eu.kanade.tachiyomi.data.ai.AiModelRoles.statusLines(
             eu.kanade.tachiyomi.data.ai.AiModelRoles.ocrTarget(
                 engineId = ocrEngine.name,
                 engineTitle = mihon.data.ocr.OcrPlugins.byModel(ocrEngine).title,
             ),
             chatTarget,
             orchestrator,
         )
         backendLine = if (status.available) {
             // При включённой автосмене отвечать может не та модель, что выбрана,
             // и без подписи это выглядит как «выбрали не ту». Имя ответившей
             // модели показывается в подвале каждого сообщения.
             val rotationNote = if (autoRotate) " · автосмена моделей" else ""
             (lines.joinToString(" · ") + rotationNote).trim()
         } else {
             "${backend.title} · недоступно: ${status.missing.joinToString(", ")}"
         }
     }

     LaunchedEffect(loading) {
         if (!loading) {
             elapsed = 0L
             activity = ""
         }
     }

     LaunchedEffect(loading) {
         while (loading) {
             kotlinx.coroutines.delay(1000)
             elapsed += 1
         }
     }

     val send: (String, String?, ByteArray?) -> Unit = { text, fileName, fileBytes ->
         if (text.isNotBlank() && !loading) {
             // Поле очищаем сразу при отправке: оставлять отправленный текст в
             // поле нельзя — читатель видит «не отправлено» и ждёт второй раз.
             input = ""
             runningJob = sendMessage(
                 context = context,
                 scope = scope,
                 mangaId = mangaId,
                 mangaTitle = mangaTitle,
                 chapterTitle = chapterTitle,
                 input = text,
                 attachmentsName = fileName,
                 attachmentsBytes = fileBytes,
                 history = history,
                 loading = { loading = it },
                 onScroll = scrollTo,
                 censorship = bookSettings.censorship,
                 historyChannel = historyChannel,
                 onActivity = setActivity,
                 onDone = { sessionRefresh += 1 },
             ).also {
                 // Ход завершился — ссылка больше не нужна, иначе «Стоп» отменил
                 // бы уже завершённую работу и обнулил индикатор.
                 scope.launch {
                     it.join()
                     runningJob = null
                 }
             }
             attachedName = null
             attachedBytes = null
         }
     }

     // Отправка, которая не теряет сообщение, поданное во время работы
     // агента: оно встаёт в очередь и уходит следующим ходом.
     val sendOrQueue: (String, String?, ByteArray?) -> Unit = { text, fileName, fileBytes ->
         when {
             text.isBlank() -> Unit
             // Идёт ход — копим. Больше одного сообщения в очередь не берём:
             // читателю важнее ответить сейчас, чем копить пачку.
             loading -> {
                 if (queuedMessage == null) {
                     queuedMessage = text to fileBytes
                     input = ""
                     attachedName = null
                     attachedBytes = null
                     showToast("Сообщение в очереди — уйдёт следом")
                 }
             }
             else -> send(text, fileName, fileBytes)
         }
     }

     // Стоп: прерываем ход агента и всё, что он успел запустить, — озвучку и
     // авточтение. Иначе остановленный ответ оставляет читателя вслух
     // читающую главу.
     val stopEverything: () -> Unit = {
         runningJob?.cancel()
         runningJob = null
         loading = false
         // «Сюжет» шёл своим запросом и раньше дожидался его сам: остановка
         // агента и чтения его не трогала, и пересказ дописывался на живого
         // читателя уже после «Стоп».
         val plotStopped = eu.kanade.tachiyomi.data.ai.ReadingPlotAgentHolder.agent.cancel()
+        // Сокет сам по себе отмены не знает: пока он висит, модель продолжает
+        // отвечать в никуда, и «Стоп» держал бы экран занятым до 90 секунд.
+        runCatching { eu.kanade.tachiyomi.data.ai.AiHttpServer.abortAllRequests("кнопка «Стоп» в чате") }
+        eu.kanade.tachiyomi.data.ai.AiAssistant.abortActiveRequests("кнопка «Стоп» в чате")
         eu.kanade.tachiyomi.data.ai.AiConsole.user(
             title = "Остановлено",
             detail = "агент: ${if (runningJob != null) "был в работе" else "не работал"}" +
                 (if (plotStopped) " · сюжет: запрос отменён" else ""),
         )
         onStopRequested()
         showToast("Остановлено")
     }

     // Очередь уходит сама, как только освободился агент.
     LaunchedEffect(loading, queuedMessage) {
         val next = queuedMessage
         if (!loading && next != null) {
             queuedMessage = null
             send(next.first, null, next.second)
         }
     }

     // История книги грузится один раз на книгу: перечитывать её на каждый
     // ответ нельзя — файл на диске ещё не дописан, и перезагрузка стирала бы
     // сообщение, которое агент только что сохранил.
     // Канал входит в ключ ОТДЕЛЬНО: раньше он был в одном ключе с mangaId, и
     // переключение «Чат ⇄ Отыгрыш» делало history.clear() прямо посреди
     // разговора — читатель видел пустой чат и делал вывод, что агент всё
     // забыл.
     LaunchedEffect(mangaId) {
         history.clear()
         history.addAll(AiHistoryManager.load(context, mangaId, historyChannel))
         runCatching { listState.scrollToItem((history.size - 1).coerceAtLeast(0)) }
     }
     LaunchedEffect(mangaId, historyChannel) {
         if (history.isEmpty()) return@LaunchedEffect
         val loaded = AiHistoryManager.load(context, mangaId, historyChannel)
         if (loaded.isEmpty()) return@LaunchedEffect
         history.clear()
         history.addAll(loaded)
         runCatching { listState.scrollToItem((history.size - 1).coerceAtLeast(0)) }
     }

     // Сводка сессии — отдельный эффект: она меняется после ответа агента,
     // когда выучены новые правила/источники.
     LaunchedEffect(mangaId, sessionRefresh) {
         // Сессия книги создаётся при первом входе в чат, чтобы знания и
         // история этой книги не смешивались с глобальным AI-чатом.
         if (mangaId != null) {
             sessionLine = withContext(Dispatchers.IO) {
                 eu.kanade.tachiyomi.data.ai.BookKnowledge.ensureSession(context, mangaId)
                 eu.kanade.tachiyomi.data.ai.BookKnowledge.summaryLine(context, mangaId)
             }
         } else {
             sessionLine = eu.kanade.tachiyomi.data.ai.BookKnowledge.summaryLine(context, null)
         }
     }

     val fileLauncher = rememberLauncherForActivityResult(
         ActivityResultContracts.OpenDocument(),
     ) { uri: Uri? ->
         if (uri == null) return@rememberLauncherForActivityResult
         val (name, bytes) = readUriFile(context, uri) ?: return@rememberLauncherForActivityResult
         attachedName = name
         attachedBytes = bytes
     }

     Dialog(
         properties = DialogProperties(
             usePlatformDefaultWidth = false,
             decorFitsSystemWindows = false,
         ),
         onDismissRequest = onClose,
     ) {
         Surface(modifier = Modifier.fillMaxSize()) {
             Column(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
                 Row(
                     modifier = Modifier
                         .fillMaxWidth()
                         // Диалог рисуется во весь экран (decorFitsSystemWindows =
                         // false), поэтому шапку и поле ввода надо прижать к
                         // системным отступам: иначе часы и заголовок наезжали
                         // друг на друга, а кнопка отправки — на жестовую
                         // полосу внизу.
                         .statusBarsPadding()
                         .padding(horizontal = 12.dp, vertical = 10.dp),
                     verticalAlignment = Alignment.CenterVertically,
                 ) {
                     Icon(
                         Icons.Outlined.SmartToy,
                         contentDescription = null,
                         tint = MaterialTheme.colorScheme.primary,
                         modifier = Modifier.size(22.dp),
                     )
                     Spacer(Modifier.width(8.dp))
                     Column(Modifier.weight(1f)) {
                         Text(
                             "AI-чат · $mangaTitle",
                             style = MaterialTheme.typography.titleMedium,
                             maxLines = 1,
                         )
                         Text(
                             chapterTitle ?: "читалка",
                             style = MaterialTheme.typography.bodySmall,
                             color = MaterialTheme.colorScheme.onSurfaceVariant,
                             maxLines = 1,
                         )
                         if (backendLine.isNotBlank()) {
                             Text(
                                 backendLine,
                                 style = MaterialTheme.typography.labelSmall,
                                 color = MaterialTheme.colorScheme.onSurfaceVariant,
                                 maxLines = 2,
                             )
                         }
                         if (sessionLine.isNotBlank()) {
                             Text(
                                 "Сессия книги: $sessionLine",
                                 style = MaterialTheme.typography.labelSmall,
                                 color = MaterialTheme.colorScheme.onSurfaceVariant,
                                 maxLines = 1,
                             )
                         }
                     }
                     IconButton(onClick = onClose) {
                         Icon(Icons.Outlined.Close, contentDescription = "Скрыть AI-чат")
                     }
                 }
                 // Переписка или файлы. Файлы — отдельная вкладка, а не
                 // сообщение в чате: агент создаёт их и раньше, и читателю надо
                 // увидеть весь список, а не то, что попало в последний ответ.
                 Row(
                     modifier = Modifier
                         .fillMaxWidth()
                         .padding(horizontal = 12.dp),
                     horizontalArrangement = Arrangement.spacedBy(8.dp),
                 ) {
                     FilterChip(
                         selected = tab == 0,
                         onClick = { tab = 0 },
                         label = { Text("Чат") },
                         modifier = Modifier.height(30.dp),
                     )
                     FilterChip(
                         selected = tab == 1,
                         onClick = {
                             tab = 1
                             filesRefresh++
                         },
                         label = { Text("Файлы") },
                         modifier = Modifier.height(30.dp),
                     )
                     // Сюжет: пересказ того, что уже прозвучало при чтении.
                     // Отдельная вкладка, потому что это не диалог с агентом, а
                     // его наблюдение: текст пишется сам по мере чтения.
                     FilterChip(
                         selected = tab == 2,
                         onClick = { tab = 2 },
                         label = { Text("Сюжет") },
                         modifier = Modifier.height(30.dp),
                     )
                     // Консоль: что ИИ делает прямо сейчас. Отдельный экран, а
                     // не ещё одна вкладка чата: её открывают, когда ход идёт и
                     // надо посмотреть, чем он занят.
                     FilterChip(
                         selected = false,
                         onClick = { showConsole = true },
                         label = { Text("Консоль") },
                         modifier = Modifier.height(30.dp),
                     )
                 }
                 if (showConsole) {
                     AiConsoleDialog(
                         onClose = { showConsole = false },
                         onStopEverything = stopEverything,
                     )
                 }
                 if (tab == 2) {
                     ReadingPlotPanel(mangaId = mangaId, showToast = showToast)
                 }
                 if (tab == 1) {
                     WorkspaceFilesPanel(
                         context = context,
                         refresh = filesRefresh,
                         // «Открыть» = показать файл. Раньше здесь был
                         // toShareIntent (ACTION_SEND), и кнопка открывала лист
                         // отправки: чтобы просто глянуть картинку, файл надо
                         // было сначала скопировать или отправить себе.
                         onOpen = { file ->
                             runCatching {
                                 context.startActivity(
                                     file.toViewIntent(context).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                                 )
                             }.onFailure {
                                 showToast("Не открыть ${file.name}: нет приложения для ${file.mimeType()}")
                             }
                         },
                     )
                 } else {
                 // Настройки работы с этой книгой: режим, 18+, цензура. Отдельный
                 // рядом, а не в меню: переключать их надо прямо по ходу чтения.
                 if (mangaId != null) {
                     val bookId = mangaId
                     // Профиль книги, а не Book: в UI нужны только настройки.
                     val applyProfile: ((BookKnowledge.Book) -> Unit) -> Unit = { mutate ->
                         bookSettings = BookKnowledge.updateProfile(context, bookId, mutate)
                             .let { BookChatProfile.Settings(it.mode, it.matureAllowed, it.censorship, it.title, it.edition) }
                     }
                     Row(
                         modifier = Modifier
                             .fillMaxWidth()
                             .padding(horizontal = 12.dp),
                         horizontalArrangement = Arrangement.spacedBy(6.dp),
                         verticalAlignment = Alignment.CenterVertically,
                     ) {
                         FilterChip(
                             selected = bookSettings.mode == BookChatProfile.MODE_ROLEPLAY,
                             onClick = {
                                 val next = if (bookSettings.mode == BookChatProfile.MODE_ROLEPLAY) {
                                     BookChatProfile.MODE_CHAT
                                 } else {
                                     BookChatProfile.MODE_ROLEPLAY
                                 }
                                 applyProfile { it.mode = next }
                             },
                             label = { Text(BookChatProfile.modeTitle(bookSettings.mode)) },
                             modifier = Modifier.height(30.dp),
                         )
                         FilterChip(
                             selected = bookSettings.matureAllowed,
                             onClick = { applyProfile { it.matureAllowed = !it.matureAllowed } },
                             label = { Text("18+") },
                             modifier = Modifier.height(30.dp),
                         )
                         FilterChip(
                             selected = bookSettings.censorship,
                             onClick = { applyProfile { it.censorship = !it.censorship } },
                             label = { Text("Цензура") },
                             modifier = Modifier.height(30.dp),
                         )
                     }
                 }
                 if (loading || activity.isNotBlank()) {
                     Row(
                         modifier = Modifier
                             .fillMaxWidth()
                             .padding(horizontal = 12.dp, vertical = 2.dp),
                         verticalAlignment = Alignment.CenterVertically,
                     ) {
                         if (loading) {
                             CircularProgressIndicator(Modifier.size(12.dp), strokeWidth = 2.dp)
                             Spacer(Modifier.width(6.dp))
                         }
                         Text(
                             buildString {
                                 append(if (loading) "AI думает" else "Готово")
                                 if (loading && elapsed > 0) append(" · ").append(elapsed).append(" с")
                                 if (activity.isNotBlank()) append(" · ").append(activity)
                             },
                             style = MaterialTheme.typography.labelSmall,
                             color = MaterialTheme.colorScheme.onSurfaceVariant,
                             maxLines = 2,
                         )
                     }
                 }
                 HorizontalDivider()

                 LazyColumn(
                     state = listState,
                     modifier = Modifier
                         .weight(1f)
                         .fillMaxWidth(),
                     contentPadding = androidx.compose.foundation.layout.PaddingValues(12.dp),
                     verticalArrangement = Arrangement.spacedBy(8.dp),
                 ) {
                     if (history.isEmpty() && !loading) {
                         item {
                             Text(
                                 "Спросите что угодно о книге «$mangaTitle»: " +
                                     "сюжет, персонажи, порядок чтения, перевод реплик, " +
                                     "«нарисуй лого», «сделай заметку»… AI умеет создавать " +
                                     "файлы в workspace, а результат можно скачать.",
                                 style = MaterialTheme.typography.bodyMedium,
                                 color = MaterialTheme.colorScheme.onSurfaceVariant,
                                 textAlign = TextAlign.Center,
                                 modifier = Modifier
                                     .fillMaxWidth()
                                     .padding(vertical = 16.dp),
                             )
                         }
                     }

                     itemsIndexed(history) { index, msg ->
                         ChatBubble(
                             context = context,
                             msg = msg,
                             isMine = msg.role == "user",
                             canPlay = msg.role == "ai",
                             onCopy = {
                                 val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE)
                                     as? ClipboardManager
                                 clipboard?.setPrimaryClip(ClipData.newPlainText("AI-чат", msg.text))
                                 showToast("Скопировано")
                             },
                             onChoice = { choice ->
                                 if (!loading) send(choice, null, null)
                             },
                             onRetry = {
                                 if (!loading) {
                                     history.remove(msg)
                                     send(msg.text, null, null)
                                 }
                             },
                             onDelete = {
                                 // Пока идёт ход, ответ ещё будет дописан в
                                 // историю — и удалённое сообщение вернулось бы
                                 // вместе с ним.
                                 if (!loading) {
                                     history.remove(msg)
                                     scope.launch {
                                         AiHistoryManager.save(context, history.toList(), mangaId, historyChannel)
                                     }
                                 }
                             },
                             onSpeak = {
                                 TtsSpeaker.speak(context, msg.text)
                             },
                         )
                     }
                 }

                 AnimatedVisibility(visible = attachedName != null) {
                     Row(
                         modifier = Modifier
                             .fillMaxWidth()
                             .padding(horizontal = 12.dp, vertical = 4.dp),
                         verticalAlignment = Alignment.CenterVertically,
                     ) {
                         Icon(Icons.Outlined.AttachFile, contentDescription = null, modifier = Modifier.size(18.dp))
                         Spacer(Modifier.width(6.dp))
                         Text(
                             attachedName ?: "",
                             style = MaterialTheme.typography.bodySmall,
                             maxLines = 1,
                             modifier = Modifier.weight(1f),
                         )
                         TextButton(onClick = {
                             attachedName = null
                             attachedBytes = null
                         }) {
                             Text("Убрать")
                         }
                     }
                 }

                 QuickActionsRow(
                     enabled = !loading,
                     onImage = { input = "Нарисуй картинку: " },
                     onAudio = { input = "Создай аудиофайл (render_audio): " },
                     onVideo = { input = "Сделай видео: " },
                     onZip = { send("Упакуй workspace в zip и покажи готовый файл", null, null) },
                     onSource = { input = "Прочитай источник и выучи правила книги: " },
                     onRules = { input = "Выучи правила книги по этому тексту:\n" },
                 )

                 Row(
                     modifier = Modifier
                         .fillMaxWidth()
                         .navigationBarsPadding()
                         .imePadding()
                         .padding(horizontal = 12.dp, vertical = 8.dp),
                     verticalAlignment = Alignment.Bottom,
                 ) {
                     OutlinedIconButton(
                         onClick = { fileLauncher.launch(arrayOf("*/*")) },
                         enabled = !loading,
                     ) {
                         Icon(Icons.Outlined.AttachFile, contentDescription = "Прикрепить файл")
                     }
                     Spacer(Modifier.width(8.dp))
                     OutlinedTextField(
                         value = input,
                         onValueChange = { input = it },
                         modifier = Modifier.weight(1f),
                         placeholder = {
                             Text(
                                 if (queuedMessage != null) {
                                     "В очереди — уйдёт следом"
                                 } else {
                                     "Сообщение AI…"
                                 },
                             )
                         },
                         maxLines = 4,
                         // Ввод не блокируется на время работы агента: писать
                         // ему последовательно должно быть можно, иначе вопрос
                         // приходилось заранее писать в поле и ждать.
                         enabled = true,
                         keyboardOptions = KeyboardOptions(imeAction = ImeAction.Send),
                         keyboardActions = KeyboardActions(
                             onSend = {
                                 sendOrQueue(input.trim(), attachedName, attachedBytes)
                             },
                         ),
                     )
                     Spacer(Modifier.width(8.dp))
                     OutlinedIconButton(
                         onClick = { sendOrQueue(input.trim(), attachedName, attachedBytes) },
                         enabled = input.isNotBlank(),
                     ) {
                         Icon(Icons.AutoMirrored.Outlined.Send, contentDescription = "Отправить")
                     }
                     // Стоп виден всегда, пока идёт ход: иначе ответ агента,
                     // а вместе с ним озвучка и авточтение, нечем остановить.
                     if (loading) {
                         Spacer(Modifier.width(4.dp))
                         FilledIconButton(onClick = stopEverything) {
                             Icon(Icons.Outlined.StopCircle, contentDescription = "Остановить")
                         }
                     }
                 }

                 Row(
                     modifier = Modifier
                         .fillMaxWidth()
                         .padding(horizontal = 12.dp, vertical = 6.dp),
                     horizontalArrangement = Arrangement.End,
                 ) {
                     TextButton(onClick = { showClearConfirm = true }) {
                         Text("Очистить историю")
                     }
                 }
             }
                 }
         }
     }


     if (showClearConfirm) {
         androidx.compose.material3.AlertDialog(
             onDismissRequest = { showClearConfirm = false },
             title = { Text("Очистить историю чата?") },
             text = { Text("История этой книги будет удалена навсегда. Это действие нельзя отменить.") },
             confirmButton = {
                 Button(onClick = {
                     // «Удалено навсегда» должно означать навсегда: во время
                     // хода ответ агента дописывается в тот же список и
                     // перезаписывает файл, возвращая историю с ответом.
                     if (loading) {
                         showToast("Дождитесь окончания ответа")
                         showClearConfirm = false
                     } else {
                         history.clear()
                         scope.launch {
                             AiHistoryManager.save(context, history.toList(), mangaId, historyChannel)
                         }
                         showClearConfirm = false
                         showToast("История очищена")
                     }
                 }) {
                     Text("Очистить")
                 }
             },
             dismissButton = {
                 TextButton(onClick = { showClearConfirm = false }) { Text("Отмена") }
             },
         )
     }
 }

 private fun sendMessage(
     context: Context,
     scope: kotlinx.coroutines.CoroutineScope,
     mangaId: Long?,
     mangaTitle: String,
     chapterTitle: String?,
     input: String,
     attachmentsName: String? = null,
     attachmentsBytes: ByteArray? = null,
     history: SnapshotStateList<Msg>,
     loading: (Boolean) -> Unit,
     onScroll: (Int) -> Unit,
     /** Настройки книги на момент отправки: цензура применяется к ответу. */
     censorship: Boolean = true,
     /** Канал истории на момент отправки, чтобы ответ не попал в чужую переписку. */
     historyChannel: String = AiHistoryManager.CHANNEL_CHAT,
     onActivity: (String) -> Unit = {},
     /** Вызывается после сохранения ответа: пора перечитать сводку сессии. */
     onDone: () -> Unit = {},
 ): kotlinx.coroutines.Job {
     loading(true)
     onActivity("Запрос к модели…")
     // Job возвращаем наружу, чтобы кнопка «Стоп» действительно прерывала ход:
     // раньше ссылка на него не хранилась, и `cancel()` был вызовом в пустоту.
     return scope.launch {
         // Запись вопроса в историю — внутри корутины: файл истории на диске,
         // а синхронный writeText на главном потоке ронял кадры на каждом ходе.
         AiHistoryManager.append(context, history, Msg(role = "user", text = input), mangaId, historyChannel)
         val reply = try {
             chatOnce(
                 context = context,
                 mangaId = mangaId,
                 mangaTitle = mangaTitle,
                 chapterTitle = chapterTitle,
                 input = input,
                 attachmentsName = attachmentsName,
                 attachmentsBytes = attachmentsBytes,
                 history = history,
                 onProgress = onActivity,
             )
         } catch (e: CancellationException) {
             // Кнопка «Стоп»: отмена хода — не ошибка запроса. Раньше
             // runCatching глотал отмену и в историю попадал ответ
             // «Сбой запроса к AI: …», хотя читатель просто остановил агента.
             loading(false)
             onActivity("Остановлено")
             throw e
         } catch (e: Exception) {
             onActivity("Ошибка запроса")
             AiAgent.AgentReply(
                 text = "Сбой запроса к AI: ${e.message ?: e::class.java.simpleName}",
                 toolResults = emptyList(),
                 images = emptyList(),
             )
         }
         // Фильтр грубых слов — настройка читателя, применяется к тому, что
         // реально попадёт в чат и в историю, иначе «цензура» была бы только
         // словами в промпте.
         val shown = if (censorship) {
             BookChatProfile.maskCensored(reply.text)
         } else {
             reply.text
         }
         // Пакетная генерация отдаёт несколько файлов одним вызовом: показываем
         // их все отдельными карточками, иначе читатель увидит одну картинку из
         // десяти и решит, что остальные не сделаны.
         val produced = reply.toolResults.flatMap { listOfNotNull(it.fileProduced) + it.extraFiles }
         val files = (produced + reply.images)
             .distinctBy { it.absolutePath }
             .mapNotNull { eu.kanade.tachiyomi.data.ai.AiWorkspace.relPathOrNull(context, it) }
             .distinct()
         AiHistoryManager.append(
             context = context,
             history = history,
             msg = Msg(
                 role = "ai",
                 text = shown,
                 time = System.currentTimeMillis(),
                 tokens = reply.tokens,
                 model = reply.model,
                 reasoning = reply.reasoning.orEmpty(),
                 choices = reply.choices,
                 tools = reply.toolResults.map { tr ->
                     buildString {
                         append(tr.name)
                         if (tr.status == "error") append(" — ошибка")
                         if (tr.tookMs > 0) append(" · ").append(AiAgent.humanMs(tr.tookMs))
                         val produced = tr.fileProduced
                         if (produced != null) {
                             append(" · ").append(produced.name).append(' ')
                             append(produced.length() / 1024).append(" КБ")
                         }
                         if (tr.extraFiles.isNotEmpty()) {
                             append(" · ещё ").append(tr.extraFiles.size)
                         }
                     }
                 },
