                            // Задачу держим в карте: иначе ход нечем отменить,
                            // а socket.close() снаружи её бы просто заблокировал.
                            val job = scope.launch { AiAgent.run(context, text) }
                            requestJobs[s] = job
                            try {
                                job.join()
                            } finally {
                                requestJobs.remove(s)
                            }
                        }""")
