                        val error = mihon.data.ui.UiActions.validate(spec)
                        when {
                            error != null -> ToolResult(call.name, "ОШИБКА: $error", status = "error")
                            UiActionRegistry.save(context, spec) -> ToolResult(
                                call.name,
                                "Кнопка «${spec.title}» добавлена (${placement.title}, " +
                                    "эффект ${effect.title} = ${spec.value}). Откройте меню читалки.",
                            )
                            else -> ToolResult(call.name, "ОШИБКА: не удалось записать кнопку", status = "error")
                        }
                    }
                }
            }
        }
    }

    "ui_action_delete" -> {
        val id = call.args.optString("id")
        when {
            id.isBlank() -> ToolResult(call.name, "ОШИБКА: нужен id кнопки", status = "error")
            UiActionRegistry.delete(context, id) -> ToolResult(call.name, "Кнопка «$id» убрана")
            else -> ToolResult(
                call.name,
                "ОШИБКА: кнопка «$id» не найдена (встроенные не удаляются)",
                status = "error",
            )
        }
    }

    "ui_action_list" -> {
        val actions = UiActionRegistry.all(context)
        ToolResult(
            "ui_action_list",
            buildString {
                appendLine("Кнопок: ${actions.size}")
                actions.forEach { a ->
                    append("• ${a.id} — ${a.title}: ${a.placement.id}/${a.effect.id}=${a.value}")
                    if (a.builtIn) append(" [встроенная]")
                    appendLine()
                }
                appendLine("Эффекты: " + mihon.data.ui.UiEffect.entries.joinToString { "${it.id} (${it.title})" })
                append("Размещения: " + mihon.data.ui.UiPlacement.entries.joinToString { it.id })
            },
        )
    }

    "ui_tab_hide", "ui_tab_show" -> {
        val id = call.args.optString("id")
        val hide = call.name == "ui_tab_hide"
        val ok = when {
            id.isBlank() -> false
            hide -> UiTabRegistry.hide(context, id)
            else -> UiTabRegistry.show(context, id)
        }
        when {
            id.isBlank() -> ToolResult(
                call.name,
                "ОШИБКА: нужен id вкладки. Доступны: " + UiTabs.IDS.joinToString(),
                status = "error",
            )
            ok -> ToolResult(
                call.name,
                "Вкладка «${UiTab.fromId(id)?.title ?: id}» " +
                    (if (hide) "скрыта" else "возвращена") +
                    ". Панель обновилась сразу; если пользователь был на этой вкладке, " +
                    "содержимое останется до перехода на другую.",
            )
            hide && UiTabs.validate(id) != null ->
                ToolResult(call.name, "ОШИБКА: " + UiTabs.validate(id), status = "error")
            UiTab.fromId(id) == null -> ToolResult(
                call.name,
                "ОШИБКА: неизвестная вкладка «$id». Доступны: " + UiTabs.IDS.joinToString(),
                status = "error",
            )
            // Id годный, валидация прошла — значит не записался файл.
            else -> ToolResult(
                call.name,
                "ОШИБКА: не удалось записать список вкладок (workspace недоступен?)",
                status = "error",
            )
        }
    }

    "ui_tab_list" -> {
        val hidden = UiTabRegistry.hidden(context)
        ToolResult(
            "ui_tab_list",
            buildString {
                appendLine("Вкладок: ${UiTab.entries.size}, скрыто: ${hidden.size}")
                UiTab.entries.forEach { tab ->
                    append("• ${tab.id} — ${tab.title}")
                    if (tab.pinned) append(" [закреплена]")
                    if (tab.id in hidden) append(" [скрыта]")
                    appendLine()
                }
                append("Скрыть можно: " + UiTabs.IDS.filterNot { it in UiTabs.PROTECTED_IDS }.joinToString())
            },
        )
    }

    else -> {
        // Самодельный плагин? Исполняем его (http или prompt через текущий бэкенд)
        val plugin = AiPlugins.get(context, call.name)
        if (plugin != null) {
            ToolResult(call.name, AiPlugins.execute(context, plugin, call.args, chatFn))
        } else {
            ToolResult(call.name, "Неизвестный инструмент")
        }
    }
}

// ---- Реализации инструментов ----

/** Pollinations: бесплатная генерация картинок без ключа. */
suspend fun generateImage(context: Context, prompt: String, subdir: String = ""): File? = withContext(Dispatchers.IO) {
    runCatching {
        val url = "https://image.pollinations.ai/prompt/" +
            URLEncoder.encode(prompt.take(400), "UTF-8").replace("+", "%20") +
            "?width=768&height=768&nologo=true"
        val conn = AiAssistant.openConnection(url)
        conn.connectTimeout = 20_000
        conn.readTimeout = 120_000
        conn.setRequestProperty("User-Agent", "Yomikai/1.0")
        if (conn.responseCode !in 200..299) {
            conn.disconnect()
            return@runCatching null
        }
        val bytes = conn.inputStream.use { it.readBytes() }
        conn.disconnect()
        if (bytes.size < 1000) return@runCatching null

metadata.preview:
        val f = AiWorkspace.newImageFile(context, prompt, subdir)
        f.writeBytes(bytes)
        f
    }.getOrElse {
        logcat(LogPriority.WARN, it) { "Pollinations failed" }
        null
    }
}

/** Реальная проверка сайта: HTTP-статус, редиректы, время ответа. */
private fun checkSite(rawUrl: String): String {
    if (rawUrl.isBlank()) return "ОШИБКА: пустой URL"
    val url = if (rawUrl.startsWith("http")) rawUrl else "https://$rawUrl"
    blockedBySsrf(url)?.let { return it }
    return runCatching {
        val started = System.currentTimeMillis()
        val conn = AiAssistant.openConnection(url)
        conn.connectTimeout = 10_000
        conn.readTimeout = 10_000
        conn.instanceFollowRedirects = false

display.text:
            val f = AiWorkspace.newImageFile(context, prompt, subdir)
            f.writeBytes(bytes)
            f
        }.getOrElse {
            logcat(LogPriority.WARN, it) { "Pollinations failed" }
            null
        }
    }

    /** Реальная проверка сайта: HTTP-статус, редиректы, время ответа. */
    private fun checkSite(rawUrl: String): String {
        if (rawUrl.isBlank()) return "ОШИБКА: пустой URL"
        val url = if (rawUrl.startsWith("http")) rawUrl else "https://$rawUrl"
        blockedBySsrf(url)?.let { return it }
        return runCatching {
            val started = System.currentTimeMillis()
            val conn = AiAssistant.openConnection(url)
            conn.connectTimeout = 10_000
            conn.readTimeout = 10_000
            conn.instanceFollowRedirects = false
            conn.requestMethod = "GET"
            conn.setRequestProperty(
                "User-Agent",
                "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Mobile Safari/537.36",
            )
            val code = conn.responseCode
            val took = System.currentTimeMillis() - started
            val location = conn.getHeaderField("Location")
            conn.disconnect()
            when {
                code in 200..299 -> "$url — РАБОТАЕТ (HTTP $code, ${took}мс)"
                code in 300..399 -> "$url — редирект на ${location ?: "?"} (HTTP $code)"
                code == 403 -> "$url — HTTP 403: вероятно, Cloudflare-защита; в браузере может открыться"
                else -> "$url — НЕ работает (HTTP $code)"
            }
        }.getOrElse { "$url — НЕ отвечает: ${it.message?.take(100)}" }
    }

    private fun webSearch(rawQuery: String): String {
        val query = rawQuery.trim()
        if (query.isBlank()) return "ОШИБКА: пустой запрос"
        return runCatching {
            val url = "https://html.duckduckgo.com/html/?q=" + URLEncoder.encode(query, "UTF-8")
            val html = fetchText(url, 120_000)
            val rows = Regex(
                "(?is)<a[^>]+class=\"result__a\"[^>]*href=\"([^\"]+)\"[^>]*>(.*?)</a>",
            ).findAll(html).take(8).map { m ->
                val href = htmlUnescape(m.groupValues[1])
                val title = stripHtml(m.groupValues[2])
                val real = if (href.contains("uddg=")) {
                    runCatching {
                        java.net.URLDecoder.decode(
                            href.substringAfter("uddg=").substringBefore("&"),
                            "UTF-8",
                        )
                    }.getOrDefault(href)
                } else {
                    href
                }
                "• $title\n  $real"
            }.toList()
            if (rows.isEmpty()) {
                "Ничего не найдено по запросу «$query»"
            } else {
                "Результаты по «$query»:\n" + rows.joinToString("\n")
            }
        }.getOrElse { "ОШИБКА поиска: ${it.message?.take(120)}" }
    }

    private fun webFetch(rawUrl: String, maxChars: Int): String {
        val url = rawUrl.trim()
        if (url.isBlank()) return "ОШИБКА: пустой URL"
        val normalized = if (url.startsWith("http")) url else "https://$url"
        blockedBySsrf(normalized)?.let { return it }
        return runCatching {
            val html = fetchText(normalized, maxChars.coerceIn(500, 60_000))
            val text = stripHtml(
                html
                    .replace(Regex("(?is)<script.*?</script>"), " ")
                    .replace(Regex("(?is)<style.*?</style>"), " "),
            ).replace(Regex("\\s{2,}"), " ").trim()
            if (text.isBlank()) {
                "$normalized — страница без текста (вероятно, JS-сайт)"
            } else {
                text.take(maxChars.coerceIn(500, 60_000))
            }
        }.getOrElse { "ОШИБКА загрузки: ${it.message?.take(120)}" }
    }

    /**
     * Скриншот ВЕБ-страницы. Без него «посмотри страницу и сделай похожее»
     * было нечем выполнить: `web_fetch` отдаёт только текст, а `see_page`
     * смотрит на страницу книги в читалке — то есть на совсем другую картинку.
     *
     * На устройстве нет headless-браузера, поэтому рендерим внешним сервисом
     * (mshots/thum.io, без ключа) и сразу спрашиваем vision — иначе агент
     * получил бы файл и должен был догадаться, что с ним делать.
     */
    private suspend fun webScreenshot(
        context: Context,
        rawUrl: String,
        width: Int,
        question: String,
    ): ToolResult {
        val url = rawUrl.trim()
        if (url.isBlank()) return ToolResult("web_screenshot", "ОШИБКА: пустой URL", status = "error")
        if (!url.startsWith("http")) return ToolResult("web_screenshot", "ОШИБКА: нужен полный URL с http(s)", status = "error")
        blockedBySsrf(url)?.let { return ToolResult("web_screenshot", it, status = "error") }
        val enc = java.net.URLEncoder.encode(url, "UTF-8")
        val services = listOf(
            "https://s.wordpress.com/mshots/v1/$enc?w=$width" to "mshots",
            "https://image.thum.io/get/width/$width/noanimate/$enc" to "thum.io",
        )
        var lastError = "сервис не ответил"
        for ((endpoint, label) in services) {
            val bytes = runCatching { downloadBytes(endpoint, 30_000) }.getOrNull()
            if (bytes == null || bytes.size < 2_000 || !looksLikeImage(bytes)) {
                lastError = if (bytes != null && bytes.size < 2_000) {
                    "$label вернул ${bytes.size} Б — это не скриншот (страница отдала заглушку или редирект)"
                } else {
                    "$label недоступен"
                }
                continue
            }
            val f = AiWorkspace.newImageFile(context, "web", sanitizeForFile(url))
            f.writeBytes(bytes)
            val rel = AiWorkspace.relPath(context, f)
            val answer = askAboutImageFile(
                f,
                question.ifBlank { "Опиши эту веб-страницу: вёрстка, цвета, шрифты, композиция, и что именно можно повторить." },
            )
            return ToolResult(
                "web_screenshot",
                buildString {
                    append("Скриншот $url сохранён: ").append(rel)
                    append(" (").append(bytes.size / 1024).append(" КБ, ширина ").append(width).append(")")
                    if (answer != null) {
                        append("\n\nЧто на скриншоте (vision-модель):\n").append(answer)
                    } else {
                        append(
                            "\n\nВопрос к vision-модели не задан: нужен движок ZenFree, Google AI или OpenRouter. " +
                                "Посмотреть картинку позже можно see_image {\"name\":\"" + rel + "\"," +
                                "\"question\":\"...\"}.",
                        )
                    }
                },
                fileProduced = f,
            )
        }
        return ToolResult(
            "web_screenshot",
            "ОШИБКА: скриншот не получен ($lastError). Для текста страницы используй web_fetch — " +
                "он отдаст текст без разметки.",
            status = "error",
        )
    }

    private fun looksLikeImage(bytes: ByteArray): Boolean =
        (bytes.size > 8 && bytes[0] == 0x89.toByte() && bytes[1] == 0x50.toByte()) || // PNG
            (bytes.size > 3 && bytes[0] == 0xFF.toByte() && bytes[1] == 0xD8.toByte()) || // JPEG
            (bytes.size > 12 && bytes[0] == 'R'.code.toByte() && bytes[1] == 'I'.code.toByte()) || // RIFF/WEBP
            (bytes.size > 3 && bytes[0] == 'G'.code.toByte() && bytes[1] == 'I'.code.toByte()) // GIF

    private fun downloadBytes(url: String, timeoutMs: Int): ByteArray? {
        val conn = AiAssistant.openConnection(url)
        conn.connectTimeout = 12_000
        conn.readTimeout = timeoutMs
        conn.instanceFollowRedirects = true
        conn.requestMethod = "GET"
        conn.setRequestProperty(
            "User-Agent",
            "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Mobile Safari/537.36",
        )
        return try {
            conn.getInputStream().use { it.readBytes() }
        } finally {
            conn.disconnect()
        }
    }

    private fun sanitizeForFile(url: String): String =
        url.removePrefix("https://").removePrefix("http://")
            .substringBefore('/')
            .replace(Regex("[^A-Za-z0-9._-]"), "_")
            .take(30)
            .ifBlank { "page" }

    /**
 * Не пускает инструменты агента во внутреннюю сеть телефона.
 *
 * Адреса приходят из текста: из распознанной реплики на странице манги, из
 * вложения или из ответа предыдущего `web_fetch`. Без проверки модель,
 * подхватившая оттуда инструкцию вроде «вызови web_fetch на 192.168.1.1»,
 * читала бы ответы и печатала их в чат — то есть съезжала по домашнему
 * роутеру и NAS. Возвращает текст ошибки, если адрес запрещён, и null иначе.
 */
private fun blockedBySsrf(rawUrl: String): String? {
    val uri = runCatching { java.net.URI(rawUrl) }.getOrNull()
        ?: return "ОШИБКА: не разобрался адрес «$rawUrl»"
    val scheme = uri.scheme?.lowercase()
    if (scheme != "http" && scheme != "https") {
        return "ОШИБКА: схема «${scheme ?: "?"}» не поддерживается, нужен http/https"
    }
    val host = uri.host?.trim('[', ']').orEmpty()
    if (host.isBlank()) return "ОШИБКА: в адресе «$rawUrl» нет хоста"

    val addresses = runCatching {
        java.net.InetAddress.getAllByName(host)
    }.getOrElse { return "ОШИБКА: не удалось разрешить «$host»" }
    if (addresses.isEmpty()) return "ОШИБКА: не удалось разрешить «$host»"

    for (address in addresses) {
        if (address.isLoopbackAddress || address.isAnyLocalAddress || address.isLinkLocalAddress ||
            address.isSiteLocalAddress || address.isMulticastAddress
        ) {
            return "ОШИБКА: «$host» — адрес внутренней сети, инструменты ходят только в интернет"
        }
    }
    return null
}

private fun fetchText(url: String, maxChars: Int): String {
        val conn = AiAssistant.openConnection(url)
        conn.connectTimeout = 12_000
        conn.readTimeout = 12_000
        conn.instanceFollowRedirects = true
        conn.requestMethod = "GET"
        conn.setRequestProperty(
            "User-Agent",
            "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Mobile Safari/537.36",
        )
        conn.setRequestProperty("Accept-Language", "ru,en;q=0.8")
        return try {
            val stream = conn.getInputStream()
            val text = stream.bufferedReader(Charsets.UTF_8).use { it.readText() }
            if (text.length > maxChars) text.take(maxChars) else text
        } finally {
            conn.disconnect()
        }
    }

    private fun stripHtml(raw: String): String {
        val unescaped = htmlUnescape(raw)
        return unescaped
            .replace(Regex("(?is)<br\\s*/?>"), "\n")
            .replace(Regex("(?is)</(p|div|li|tr|h[1-6])>"), "\n")
            .replace(Regex("(?is)<[^>]+>"), " ")
            .replace(Regex("[ \\t\\x0B\\f]+"), " ")
            .trim()
    }

    private fun htmlUnescape(raw: String): String = raw
        .replace("&amp;", "&")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&#39;", "'")
        .replace("&apos;", "'")
        .replace("&nbsp;", " ")

    private fun listExtensions(): String {
        val sources = sourceManager.getAll().filterIsInstance<CatalogueSource>()
        if (sources.isEmpty()) return "Расширения не установлены"
        val disabled = sourcePrefs.disabledSources.get()
        return sources.take(60).joinToString("\n") { s ->
            val domain = (s as? HttpSource)?.baseUrl ?: "локальный"
            val state = if (s.id.toString() in disabled) "СКРЫТ" else "виден"
            "• ${s.name} [${s.lang}] — $domain — $state (id=${s.id})"
        }
    }

    /** Скрыть/показать источники по подстроке имени, языка или домена. */
    private fun filterExtensions(hide: String, show: String): String {
        val sources = sourceManager.getAll().filterIsInstance<CatalogueSource>()
        val pref = sourcePrefs.disabledSources
        val current = pref.get().toMutableSet()
        val log = StringBuilder()
        fun matches(s: CatalogueSource, q: String): Boolean {
            val d = (s as? HttpSource)?.baseUrl.orEmpty()
            return s.name.contains(q, true) || s.lang.contains(q, true) || d.contains(q, true)
        }
        if (hide.isNotBlank()) {
            val victims = sources.filter { matches(it, hide) }
            victims.forEach { current += it.id.toString() }
            log.append("Скрыто ${victims.size}: ${victims.joinToString { it.name }.take(200)}\n")
        }
        if (show.isNotBlank()) {
            val victims = sources.filter { matches(it, show) }
            victims.forEach { current -= it.id.toString() }
            log.append("Показано ${victims.size}: ${victims.joinToString { it.name }.take(200)}\n")
        }
        pref.set(current)
        return log.toString().ifBlank { "Ничего не найдено по запросу" }
    }

    /**
     * Реальный поиск тайтла по включённым источникам: до 8 источников,
     * каждому 12с. Возвращает, где тайтл реально находится.
     */
    private suspend fun findManga(title: String): String {
        if (title.isBlank()) return "ОШИБКА: пустое название"
        val disabled = sourcePrefs.disabledSources.get()
        val sources = sourceManager.getAll().filterIsInstance<CatalogueSource>()
            .filter { it.id.toString() !in disabled }
            .take(8)
        if (sources.isEmpty()) return "Нет включённых источников"
        val sb = StringBuilder()
        for (s in sources) {
            val found = withTimeoutOrNull(12_000) {
                runCatching {
                    s.getSearchManga(1, title, eu.kanade.tachiyomi.source.model.FilterList()).mangas
                }.getOrNull()
            }
            when {
                found == null -> sb.append("• ${s.name} [${s.lang}] — таймаут/ошибка\n")
                found.isEmpty() -> sb.append("• ${s.name} [${s.lang}] — не найдено\n")
                else -> {
                    val top = found.take(3).joinToString("; ") { it.title.take(60) }
                    sb.append("• ${s.name} [${s.lang}] — НАЙДЕНО ${found.size}: $top\n")
                }
            }
        }
        return sb.toString()
    }

    /** OCR картинки-вложения текущим движком распознавания (с фолбэками). */
    suspend fun ocrAttachment(file: File): String? = withContext(Dispatchers.IO) {
        runCatching {
            val opts = BitmapFactory.Options()
            var bmp: Bitmap = BitmapFactory.decodeFile(file.absolutePath, opts) ?: return@runCatching null
            if (bmp.width > 1600) {
                val h = bmp.height * 1600 / bmp.width
                val scaled = Bitmap.createScaledBitmap(bmp, 1600, h, true)
                bmp.recycle()
                bmp = scaled
            }
            val pixels = IntArray(bmp.width * bmp.height)
            bmp.getPixels(pixels, 0, bmp.width, 0, 0, bmp.width, bmp.height)
            val image = OcrImage(bmp.width, bmp.height, pixels)
            bmp.recycle()
            val repo = Injekt.get<OcrRepository>()
            repo.recognizeText(image).trim().ifBlank { null }
        }.getOrElse {
            logcat(LogPriority.WARN, it) { "AI attachment OCR failed" }
            null
        }
    }

    /**
     * Спросить у выбранной vision-модели про кадр страницы.
     *
     * Это «глаза» оркестратора: текст страницы он и так читает через OCR, а
     * здесь получает возможность понять изображение — кто нарисован, что
     * происходит, как разбит на панели. null означает «движок не умеет
     * отвечать на вопросы» (локальный распознаватель) или ответ не пришёл;
     * оба случая не фатальны, вызывающий код продолжает разговор.
     */
    suspend fun askAboutPage(bitmap: Bitmap, question: String): String? = withContext(Dispatchers.IO) {
        runCatching {
            if (bitmap.isRecycled) return@runCatching null
            val maxSide = maxOf(bitmap.width, bitmap.height)
            val source = if (maxSide > VISION_MAX_SIDE) {
                val scale = VISION_MAX_SIDE.toFloat() / maxSide
                Bitmap.createScaledBitmap(
                    bitmap,
                    (bitmap.width * scale).toInt().coerceAtLeast(1),
                    (bitmap.height * scale).toInt().coerceAtLeast(1),
                    true,
                )
            } else {
                null
            }
            try {
                val scaled = source ?: bitmap
                val pixels = IntArray(scaled.width * scaled.height)
                scaled.getPixels(pixels, 0, scaled.width, 0, 0, scaled.width, scaled.height)
                val image = OcrImage(scaled.width, scaled.height, pixels)
                Injekt.get<OcrRepository>().askAboutImage(image, question)?.trim()
                    ?.takeIf { it.isNotEmpty() }
            } finally {
                if (source != null && !source.isRecycled) source.recycle()
            }
        }.getOrElse {
            logcat(LogPriority.WARN, it) { "AI page vision failed" }
            null
        }
    }

    private const val VISION_MAX_SIDE = 1600

    /**
     * Спросить vision-модель про файл-картинку из workspace.
     *
     * Отдельная функция, а не переиспользование askAboutPage, потому что там
     * уже есть готовая [android.graphics.Bitmap], а тут файл: его надо
     * декодировать, уменьшить (иначе в контекст уйдёт гигабайт пикселей) и
     * обязательно отдать переработанный bitmap — иначе течёт память на каждом
     * вызове. null — движок не vision, или ответ пустой.
     */
    private suspend fun askAboutImageFile(file: File, question: String): String? = withContext(Dispatchers.IO) {
        runCatching {
            if (!file.isFile) return@runCatching null
            if (file.length() > MAX_IMAGE_FILE_BYTES) {
                logcat(LogPriority.WARN) { "see_image: file too large (${file.length()} bytes)" }
                return@runCatching null
            }
            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            BitmapFactory.decodeFile(file.absolutePath, bounds)
            if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return@runCatching null
            val opts = BitmapFactory.Options().apply {
                // Выборка сразу по размеру, а не «декодировать в пол и потом
                // уменьшать»: фото с камеры весит 8 МБ, и полная декодировка
                // на телефоне означает OutOfMemory.
                inSampleSize = sampleSizeFor(bounds.outWidth, bounds.outHeight, VISION_MAX_SIDE)
            }
            val decoded = BitmapFactory.decodeFile(file.absolutePath, opts) ?: return@runCatching null
            val scaled = scaleDown(decoded, VISION_MAX_SIDE)
            try {
                val pixels = IntArray(scaled.width * scaled.height)
                scaled.getPixels(pixels, 0, scaled.width, 0, 0, scaled.width, scaled.height)
                Injekt.get<OcrRepository>()
                    .askAboutImage(OcrImage(scaled.width, scaled.height, pixels), question)
                    ?.trim()
                    ?.takeIf { it.isNotEmpty() }
            } finally {
                // Ссылка на переработанный bitmap не переживает вызов, чистим
                // явно: иначе память утекает на каждом вопросе о картинке.
                if (scaled !== decoded && !scaled.isRecycled) scaled.recycle()
                if (!decoded.isRecycled) decoded.recycle()
            }
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "see_image failed for ${file.name}" }
            null
        }
    }

    /** Файл крупнее этого не отправляем: экономия трафика и времени модели. */
    private const val MAX_IMAGE_FILE_BYTES = 12L * 1024L * 1024L

    /**
     * Степень уменьшения при декодировании. Считается из реального размера:
     * для 12000×9000 это 8, и декодирование сразу даёт 1500×1125 — в
     * пределах того, что нужно модели, вместо 108 мегапикселей в памяти.
     */
    internal fun sampleSizeFor(width: Int, height: Int, maxSide: Int): Int {
        var sample = 1
        var w = width
        var h = height
        while (maxOf(w, h) / 2 >= maxSide && sample < 16) {
            w /= 2
            h /= 2
            sample *= 2
        }
        return sample
    }

    /** Масштабирование до Vision_MAX_SIDE, если ещё не вписано. */
    private fun scaleDown(src: Bitmap, maxSide: Int): Bitmap {
        val max = maxOf(src.width, src.height)
        if (max <= maxSide) return src
        val k = maxSide.toFloat() / max
        return Bitmap.createScaledBitmap(
            src,
            (src.width * k).toInt().coerceAtLeast(1),
            (src.height * k).toInt().coerceAtLeast(1),
            true,
        )
    }

}

package eu.kanade.tachiyomi.data.ai

import android.app.Application
import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import eu.kanade.tachiyomi.network.NetworkPreferences
import mihon.domain.ocr.service.OcrPreferences
import org.json.JSONArray
import org.json.JSONObject
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.net.HttpURLConnection
import java.net.InetSocketAddress
import java.net.Proxy
import java.net.URL
import java.util.concurrent.ConcurrentHashMap

/**
 * Онлайн AI-ассистент читалки. Два провайдера, оба OpenAI-совместимые:
 *
 * • ZEN (opencode.ai/zen) — БЕЗ API-ключа. Бесплатные текстовые модели:
 *   mimo-v2.5-free, deepseek-v4-flash-free, laguna-s-2.1-free,
 *   nemotron-3-ultra-free, nemotron-3.5-lightning-free, hy3-free,
 *   big-pickle. Space Bunny Free используется отдельным vision-OCR движком.
 *
 * • OPENROUTER — по API-ключу, выбор из бесплатных «:free» моделей
 *   (список тянется живьём с /api/v1/models и фильтруется по суффиксу).
 *
 * Используется авточтением: реплики без уверенного вердикта локальной
 * морфологии батчем уходят ассистенту на определение пола говорящего.
 */
object AiAssistant {

    const val PROVIDER_ZEN = "zen"
    const val PROVIDER_OPENROUTER = "openrouter"

    /**
     * Базовые URL встроенных провайдеров. Вынесены в константы, потому что их
     * читает реестр [AiProviders]: список в настройках обязан показывать те же
     * адреса, куда реально уходит запрос.
     */
    const val ZEN_BASE_URL = "https://opencode.ai/zen/v1"
    const val OPENROUTER_BASE_URL = "https://openrouter.ai/api/v1"

    /**
     * Модели Zen, проверенные без ключа.
     *
     * Список взят из документации opencode Zen, а не придуман: там перечислены
     * именно бесплатные модели, которые отдаются без ключа. Модели, которые
     * из неё ушли (laguna-s-2.1-free, deepseek-v4-flash-free, hy3-free),
     * выброшены — они больше не существуют, и каждая попытка получить ответ
     * была чистой потерей времени.
     *
     * Порядок = приоритет ротации: первыми идут БЫСТРЫЕ без тяжёлого
     * reasoning, reasoning-модели — в хвосте. При FreeUsageLimitError
     * (rate limit конкретной модели) запрос автоматически повторяется на
     * следующей модели списка.
     */
    val ZEN_MODELS = listOf(
        "mimo-v2.6-flash-free",
        "mimo-v2.5-free",
        "nemotron-3.5-lightning-free",
        "nemotron-3-ultra-free",
        "big-pickle",
        "space-bunny-free",
        "ling-3.0-flash-fin-free",
    )

    /** Запасной список OpenRouter :free на случай оффлайна при первом открытии. */
    val OPENROUTER_FREE_FALLBACK = listOf(
        "nvidia/nemotron-3-nano-30b-a3b:free",
        "poolside/laguna-s-2.1:free",
        "z-ai/glm-5.2:free",
        "google/gemma-4-31b-it:free",
        "nvidia/nemotron-3-super-120b-a12b:free",
    )

    private fun prefs(): OcrPreferences = Injekt.get()

    /**
     * Контекст приложения для реестров, которые читают файлы пользователя
     * (`AiProviders`, `AiPlugins`). Зарегистрирован в Injekt через
     * `AppModule.addSingleton(app)`.
     */
    private fun appContext(): Context = Injekt.get<Application>()

    /**
     * Запрос к провайдеру пользователя (любой OpenAI-совместимый endpoint:
     * Ollama, LM Studio, llama.cpp server, корпоративный прокси).
     *
     * Временные сбои ретраятся на том же адресе, как в ветке OpenRouter.
     * Автосмены на Zen здесь НАМЕРЕНО нет: пользователь явно выбрал свой
     * endpoint, и тихая отправка его промпта стороннему сервису была бы
     * неверной. Ошибка возвращается как `null` — вызывающий код деградирует
     * мягко, как и при недоступности встроенных провайдеров.
     */
    private suspend fun customProviderChat(
        spec: AiProviders.Spec,
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int,
        modelOverride: String? = null,
    ): ChatReply? {
        val url = AiProviders.chatCompletionsUrl(spec.baseUrl)
        if (url == null) {
            lastFailureMessage = "${spec.id}: некорректный baseUrl «${spec.baseUrl}»"
            logcat(LogPriority.WARN) { "Custom provider ${spec.id} has an invalid baseUrl" }
            return null
        }
        // Модель роли идёт первой: провайдер OpenAI-совместим, и человек,
        // выбравший её для роли, ждёт именно её. Свою модель оставляем
        // запасным вариантом, чтобы опечатка в id не убивала чат целиком.
        val models = listOfNotNull(modelOverride?.takeIf { it.isNotBlank() }, spec.model)
            .distinct()
        var reply: ChatReply? = null
        for (model in models) {
            var got: ChatReply? = null
            for (delayMs in longArrayOf(0, 1_200, 2_500)) {
                if (delayMs > 0) kotlinx.coroutines.delay(delayMs)
                when (val outcome = chatRawOutcome(url, model, spec.apiKey, userPrompt, systemPrompt, maxTokens)) {
                    is Outcome.Ok -> {
                        got = outcome.reply
                        break
                    }
                    Outcome.Transient -> continue
                    else -> break
                }
            }
            if (got != null) {
                reply = got
                break
            }
        }
        if (reply == null) {
            logcat(LogPriority.WARN) { "Custom provider ${spec.id} (${models.joinToString()}) did not answer" }
        }
        return reply
    }

    private val modelCooldownUntil = ConcurrentHashMap<String, Long>()

    @Volatile
    private var zenLastSuccessAt: Long = 0L

    @Volatile
    private var zenLastBlockedAt: Long = 0L

    /**
     * Что реально отвечает Zen. Отчёт о возможностях обязан опираться на
     * фактический ответ, а не на наличие сети: раньше он писал «доступно» по
     * одному факту подключения, и агент затем по инструкции «не повторяй
     * недоступное» продолжал биться в закрытую дверь вместо перехода на
     * рабочий путь.
     */
    fun zenState(): ZenAvailability.State = ZenAvailability.decide(
        lastSuccessAt = zenLastSuccessAt,
        lastBlockedAt = zenLastBlockedAt,
        now = System.currentTimeMillis(),
    )

    private fun noteZenSuccess() {
        zenLastSuccessAt = System.currentTimeMillis()
        zenLastBlockedAt = 0L
    }

    private fun noteZenBlocked() {
        zenLastBlockedAt = System.currentTimeMillis()
    }

    @Volatile
    private var lastFailureMessage: String = ""

    fun lastFailure(): String = lastFailureMessage

    /**
     * Raw AI calls used URLConnection directly and silently ignored the proxy
     * configured in Settings → Advanced. Route Zen/OpenRouter through the same
     * HTTP/SOCKS proxy, including optional Basic proxy authentication.
     */
    internal fun openConnection(url: String): HttpURLConnection {
        val network = Injekt.get<NetworkPreferences>()
        val rawHost = network.proxyHost.get().trim()
        val enabled = network.enableProxy.get() && rawHost.isNotBlank()
        val target = URL(url)
        if (!enabled) return target.openConnection() as HttpURLConnection

        val parsed = runCatching {
            val withScheme = if (rawHost.contains("://")) rawHost else "http://$rawHost"
            URL(withScheme)
        }.getOrNull()
        val host = parsed?.host?.takeIf { it.isNotBlank() }
            ?: rawHost.substringBefore(':').substringBefore('/')
        val explicitPort = parsed?.port?.takeIf { it > 0 }
            ?: rawHost.substringAfter(':', "").substringBefore('/').toIntOrNull()
        val port = explicitPort ?: network.proxyPort.get().coerceIn(1, 65_535)
        val type = if (network.proxyType.get() == 1) Proxy.Type.SOCKS else Proxy.Type.HTTP
        val connection = target.openConnection(Proxy(type, InetSocketAddress(host, port))) as HttpURLConnection
        val user = network.proxyUser.get()
        if (user.isNotBlank() && type == Proxy.Type.HTTP) {
            val credentials = "$user:${network.proxyPassword.get()}"
            val encoded = android.util.Base64.encodeToString(
                credentials.toByteArray(Charsets.UTF_8),
                android.util.Base64.NO_WRAP,
            )
            connection.setRequestProperty("Proxy-Authorization", "Basic $encoded")
        }
        return connection
    }

    private fun coolingDown(model: String): Boolean =
        (modelCooldownUntil[model] ?: 0L) > System.currentTimeMillis()

    private fun coolDown(model: String, durationMs: Long) {
        modelCooldownUntil[model] = System.currentTimeMillis() + durationMs
    }

    /** Запись скрытого AI-чата: что спросили, что ответила модель, сколько заняло. */
    data class LogEntry(
        val time: Long,
        val model: String,
        val prompt: String,
        val answer: String,
        val tookMs: Long,
    )

    /** Кольцевой журнал последних обращений — «скрытый чат» ассистента. */
    private val logBuffer = ArrayDeque<LogEntry>()

    @Synchronized
    fun log(): List<LogEntry> = logBuffer.toList()

    @Synchronized
    private fun addLog(e: LogEntry) {
        logBuffer.addLast(e)
        while (logBuffer.size > 40) logBuffer.removeFirst()
    }

    /** Живой список бесплатных моделей OpenRouter (":free"). */
    suspend fun fetchOpenRouterFreeModels(): List<String> = withContext(Dispatchers.IO) {
        runCatching {
            val conn = openConnection("$OPENROUTER_BASE_URL/models")
            conn.connectTimeout = 10_000
            conn.readTimeout = 20_000
            val body = conn.inputStream.use { it.readBytes().toString(Charsets.UTF_8) }
            conn.disconnect()
            val arr = JSONObject(body).getJSONArray("data")
            buildList {
                for (i in 0 until arr.length()) {
                    val id = arr.getJSONObject(i).optString("id")
                    if (id.endsWith(":free")) add(id)
                }
            }.sorted()
        }.getOrDefault(OPENROUTER_FREE_FALLBACK)
    }

    /** Полный ответ модели: текст, «размышления» (reasoning), реальная модель. */
    data class ChatReply(
        val content: String,
        val reasoning: String?,
        val model: String,
        /** Токены запроса+ответа (usage.total_tokens; 0 если провайдер не отдал). */
        val tokens: Int = 0,
        /** false when provider stopped because max_tokens was exhausted. */
        val complete: Boolean = true,
    )

    /**
     * Один chat-запрос выбранному провайдеру. null при любой ошибке —
     * вызывающий код обязан деградировать мягко (нейтральный голос,
     * пропуск перевода и т.п.).
     */
    suspend fun chat(userPrompt: String, systemPrompt: String? = null, maxTokens: Int = 500): String? =
        chatFull(userPrompt, systemPrompt, maxTokens)?.content

    /**
     * Как chat(), но с reasoning-блоком и именем фактически ответившей
     * модели (при автосмене может отличаться от выбранной).
     *
     * [modelOverride] — модель отдельной роли (например, оркестратора читалки).
     * Пустое значение = обычный выбор провайдера, поведение прежнее.
     */
    suspend fun chatFull(
        userPrompt: String,
        systemPrompt: String? = null,
        maxTokens: Int = 500,
        modelOverride: String? = null,
    ): ChatReply? =
        withContext(Dispatchers.IO) {
            val p = prefs()
            val provider = p.aiProvider().get()
            val override = modelOverride?.takeIf { it.isNotBlank() }

            // Провайдер пользователя из реестра AiProviders (свой base URL,
            // модель и ключ). Проверяется первым: id у него свой, поэтому ветки
            // Zen/OpenRouter ниже не затрагиваются.
            val custom = AiProviders.userProvider(appContext(), provider)
            if (custom != null) {
                return@withContext customProviderChat(
                    custom, userPrompt, systemPrompt, maxTokens, override,
                )
            }

            val key = p.openrouterApiKey().get()
            if (provider == PROVIDER_OPENROUTER && key.isNotBlank()) {
                val model = override
                    ?: p.openrouterFreeModel().get().ifBlank { OPENROUTER_FREE_FALLBACK.first() }
                if (coolingDown(model) && p.aiAutoRotate().get()) {
                    return@withContext zenChatWithRotation(userPrompt, systemPrompt, maxTokens, override)
                }
                // Временные сбои сети/прокси ретраим на той же модели,
                // прежде чем считать OpenRouter «упавшим».
                var reply: ChatReply? = null
                var lastOutcome: Outcome? = null
                for (delayMs in longArrayOf(0, 1_200, 2_500)) {
                    if (delayMs > 0) kotlinx.coroutines.delay(delayMs)
                    val outcome = chatRawOutcome(
                        "$OPENROUTER_BASE_URL/chat/completions",
                        model, key, userPrompt, systemPrompt, maxTokens,
                    )
                    lastOutcome = outcome
                    when (outcome) {
                        is Outcome.Ok -> {
                            reply = outcome.reply
                            modelCooldownUntil.remove(model)
                        }
                        Outcome.Transient -> continue
                        else -> {}
                    }
                    break
                }
                if (reply == null) {
                    // У OpenRouter свой 403 — это про конкретный ключ или
                    // модель. Дальше по коду всё равно пробуется Zen, поэтому
                    // cooldown ставится, а не выход.
                    coolDown(
                        model,
                        when (lastOutcome) {
                            Outcome.RateLimited -> 15 * 60_000L
                            Outcome.Fatal -> 5 * 60_000L
                            else -> 90_000L
                        },
                    )
                }
                if (reply != null || !p.aiAutoRotate().get()) return@withContext reply
                // Автосмена: OpenRouter реально недоступен → пробуем Zen
                return@withContext zenChatWithRotation(userPrompt, systemPrompt, maxTokens, override)
            }
            if (provider == PROVIDER_OPENROUTER) {
                logcat(LogPriority.WARN) { "OpenRouter selected but no API key; falling back to Zen" }
            }
            zenChatWithRotation(userPrompt, systemPrompt, maxTokens, override)
        }

    /**
     * Zen с авторотацией: выбранная модель первая, при rate limit / ошибке —
     * следующая из списка. Бесплатные лимиты Zen помодельные, поэтому
     * ротация почти всегда находит живую модель. Тумблер «Автосмена моделей»
     * (pref_ai_auto_rotate) ограничивает попытки одной выбранной моделью.
     */
    /**
     * Zen с ПРАВИЛЬНОЙ ротацией (фикс по жалобе пользователя):
     *  • настоящий rate limit (429/FreeUsageLimit) → сразу СЛЕДУЮЩАЯ модель;
     *  • временный сбой (таймаут/5xx/обрыв прокси) → до 2 ретраев ТОЙ ЖЕ
     *    модели с паузой 1.2с/2.5с — рабочая модель не бросается из-за
     *    моргнувшей сети;
     *  • фатальная ошибка → следующая модель.
     */
    private suspend fun zenChatWithRotation(
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int,
        preferredOverride: String? = null,
    ): ChatReply? {
        // Модель, названная ролью, идёт первой ЛЮБОЙ: каталог [ZEN_MODELS] — это
        // список для ротации, а не белый список. Раньше незнакомый id молча
        // заменялся моделью чата, и статус обещал несуществующий выбор.
        val preferred = preferredOverride?.takeIf { it.isNotBlank() }
            ?: prefs().zenModel().get().ifBlank { ZEN_MODELS.first() }
        val configuredOrder = if (prefs().aiAutoRotate().get()) {
            listOf(preferred) + ZEN_MODELS.filter { it != preferred }
        } else {
            listOf(preferred)
        }
        // A model that just returned a limit/5xx must not become first again
        // when the user taps Retry. Keep it on cooldown across chat turns.
        val order = configuredOrder.filterNot(::coolingDown).ifEmpty { configuredOrder }
        val retryDelaysMs = longArrayOf(1_200, 2_500)
        for (m in order) {
            var attempt = 0
            while (true) {
                when (val res = chatRawOutcome(
                    "$ZEN_BASE_URL/chat/completions",
                    m, "", userPrompt, systemPrompt, maxTokens,
                )) {
                    is Outcome.Ok -> {
                        modelCooldownUntil.remove(m)
                        noteZenSuccess()
                        return res.reply
                    }
                    Outcome.RateLimited -> {
                        coolDown(m, 15 * 60_000L)
                        break
                    }
                    Outcome.Fatal -> {
                        coolDown(m, 5 * 60_000L)
                        break
                    }
                    // 403 FreeTierError — это про конкретную модель, а не про
                    // весь Zen разом. Доказано тем, что OCR-движок ходит в тот
                    // же эндпоинт с той же моделью space-bunny-free и работает.
                    // Раньше здесь был выход сразу, и первая закрытая модель
                    // убивала чат целиком, не дав дойти до рабочей.
                    Outcome.FreeTierBlocked -> {
                        coolDown(m, 5 * 60_000L)
                        break
                    }
                    Outcome.Transient -> {
                        if (attempt >= retryDelaysMs.size) {
                            coolDown(m, 90_000L)
                            break
                        }
                        kotlinx.coroutines.delay(retryDelaysMs[attempt])
                        attempt++
                    }
                }
            }
        }
        return null
    }

    /**
     * Исход одного запроса. Нужен, чтобы ротация вела себя ПРАВИЛЬНО
     * (жалоба пользователя: «rate limit неверный — у одной модели
     * правильный, у другой просто сбои сети/прокси, потом отвечает»):
     *  • Ok            — ответ получен;
     *  • RateLimited   — НАСТОЯЩИЙ лимит (HTTP 429 или FreeUsageLimitError
     *                    в теле) → переключаться на следующую модель;
     *  • Transient     — временный сбой (таймаут, 5xx, обрыв соединения,
     *                    прокси) → ретраить ТУ ЖЕ модель с паузой, а не
     *                    убегать с рабочей модели;
     *  • Fatal         — постоянная ошибка модели (4xx кроме 429, кривой
     *                    ответ) → следующая модель.
     */
    private sealed class Outcome {
        data class Ok(val reply: ChatReply) : Outcome()
        object RateLimited : Outcome()
        object Transient : Outcome()
        object Fatal : Outcome()
        /**
         * Бесплатные модели Zen закрыты для сторонних клиентов самим
         * OpenCode. Закрытие помодельное, а не общее: OCR-движок в этом же
         * приложении ходит в тот же эндпоинт с моделью `space-bunny-free` и
         * получает ответ. Поэтому исход означает «пропусти эту модель», а не
         * «сдавайся» — иначе чат переставал работать из-за одной закрытой
         * модели, не дойдя до рабочей.
         */
        object FreeTierBlocked : Outcome()
    }

    /**
     * Ответ, которым OpenCode отказывает стороннему клиенту на бесплатных
     * моделях Zen: HTTP 403 c `FreeTierError` / «can only be used from within
     * OpenCode». Проверяется по телу ответа, а не по коду: 403 у провайдера
     * бывает и по другим причинам.
     */
    internal fun isZenFreeTierBlocked(code: Int, body: String): Boolean =
        code == 403 && (
            body.contains("FreeTierError", ignoreCase = true) ||
                body.contains("only be used from within OpenCode", ignoreCase = true)
            )

    /** Правдивое объяснение вместо «проверьте прокси»: прокси тут ни при чём. */
    const val FREE_TIER_BLOCKED_MESSAGE =
        "OpenCode отдаёт бесплатные модели Zen только своему собственному клиенту " +
            "(HTTP 403 FreeTierError) — ни ключ, ни прокси, ни смена модели это не лечит. " +
            "Бесплатно и легально: модели «:free» в OpenRouter (ключ бесплатный), " +
            "локальная LLM или бэкенд «Полу-онлайн», где крутится настоящий opencode."

    private fun chatRawOutcome(
        url: String,
        model: String,
        apiKey: String,
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int = 500,
    ): Outcome {
        val startedAt = System.currentTimeMillis()
        // Соединение живёт вне try: disconnect обязан сработать и на таймауте,
        // и на SSL-ошибке, и на 5xx — иначе сокет и буферы висели до сборки GC.
        // На мобильной сети это почти каждый второй запрос, а на модель
        // делается до трёх попыток с ротацией — утечка накапливалась за ход.
        var conn: HttpURLConnection? = null
        return try {
            // Эндпоинт и форма запроса зависят от семейства модели: Claude
            // ждёт /messages, GPT и Muse — /responses, Gemini — свой путь.
            // Раньше всё уходило в /chat/completions, поэтому модели этих
            // семейств не отвечали вовсе и выглядели сломанными.
            val body = ZenProtocol.requestBody(model, userPrompt, systemPrompt, maxTokens)
            // Базовый адрес приходит от вызывающего кода с хвостом
            // /chat/completions; подставляем эндпоинт, который нужен модели.
            val actualUrl = if (url.endsWith("/chat/completions")) {
                ZenProtocol.urlFor(url.removeSuffix("/chat/completions"), model)
            } else {
                url
            }

            val rawConn = openConnection(actualUrl)
            conn = rawConn
            rawConn.requestMethod = "POST"
            rawConn.doOutput = true
            rawConn.connectTimeout = 15_000
            rawConn.readTimeout = 90_000
            rawConn.setRequestProperty("Content-Type", "application/json")
            if (apiKey.isNotBlank()) rawConn.setRequestProperty("Authorization", "Bearer $apiKey")

            rawConn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
            val code = rawConn.responseCode
            val text = (if (code in 200..299) rawConn.inputStream else rawConn.errorStream)
                ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
            if (code !in 200..299) {
                // Отдельная судьба для «бесплатных» моделей Zen: OpenCode
                // отдаёт их только своему же клиенту (проверка по User-Agent),
                // поэтому ни ключ, ни прокси, ни ротация тут не помогут. Ловим
                // ДО классификации по коду, иначе 403 уходит в Fatal, и каждая
                // модель каталога получает cooldown — после чего даже рабочий
                // путь выглядит сломанным на 5 минут.
                if (isZenFreeTierBlocked(code, text)) {
                    lastFailureMessage = FREE_TIER_BLOCKED_MESSAGE
                    noteZenBlocked()
                    logcat(LogPriority.WARN) { "Zen free tier blocked for $model (HTTP $code)" }
                    return Outcome.FreeTierBlocked
                }
                lastFailureMessage = "$model: HTTP $code — ${text.take(160)}"
                logcat(LogPriority.WARN) { "AI assistant HTTP $code ($model): ${text.take(160)}" }
                addLog(
                    LogEntry(
                        startedAt, model, userPrompt.take(200),
                        "HTTP $code: ${text.take(120)}",
                        System.currentTimeMillis() - startedAt,
                    ),
                )
                // Классификация: настоящий лимит vs временный сбой vs фатально
                val isLimit = code == 429 ||
                    text.contains("FreeUsageLimit", ignoreCase = true) ||
                    text.contains("rate_limit", ignoreCase = true) ||
                    text.contains("quota", ignoreCase = true)
                return when {
                    isLimit -> Outcome.RateLimited
                    code in 500..599 || code == 408 -> Outcome.Transient // 5xx/таймаут — прокси/сайт барахлит
                    else -> Outcome.Fatal
                }
            }
            // Разбор формы ответа — по семейству модели. Раньше читался
            // только choices[0].message, поэтому у Claude (блок thinking),
            // у Responses (отдельный output) и у Gemini (флаг thought)
            // размышления терялись, и в чате появлялось «🤔 null».
            val parsed = ZenProtocol.parse(text, model)
            val answer = parsed.content
            val reasoning = parsed.reasoning
            addLog(LogEntry(startedAt, model, userPrompt.take(200), (answer ?: "<пусто>").take(200), System.currentTimeMillis() - startedAt))
            answer?.let {
                lastFailureMessage = ""
                Outcome.Ok(
                    ChatReply(
                        content = it,
                        reasoning = reasoning,
                        model = model,
                        tokens = parsed.tokens,
                        complete = parsed.complete,
                    ),
                )
            } ?: Outcome.Fatal
        } catch (e: Exception) {
            lastFailureMessage = "$model: ${e.javaClass.simpleName} — ${e.message?.take(160)}"
            addLog(LogEntry(startedAt, model, userPrompt.take(200), "ОШИБКА: ${e.message?.take(120)}", System.currentTimeMillis() - startedAt))
            logcat(LogPriority.WARN, e) { "AI assistant call failed ($model)" }
            // Сетевые исключения (SocketTimeout, ConnectException, SSL,
            // UnknownHost, обрыв прокси) — ВРЕМЕННЫЕ: модель не виновата
            Outcome.Transient
        } finally {
            conn?.disconnect()
        }
    }

    /** Строка подготовленного кадра: говорить ли, каким полом, каким текстом. */
    data class PreparedLine(val speak: Boolean, val gender: String?, val text: String)

    /**
     * ГЛАВНЫЙ шаг конвейера (по требованию пользователя): текст кадра
     * отправляется В ЧАТ ДО озвучки. Модель одним запросом:
     *  1) вычищает реплики, повторяющие прошлый кадр (перекрытие скролла);
     *  2) назначает пол говорящего каждой оставшейся;
     *  3) возвращает чистый текст для синтеза.
     * Протокол ответа — по строке на реплику: «N|г|текст» (г: м/ж/н) или
     * «N|-» для пропуска дубля. Всё видно в скрытом чате (журнале).
     * Таймаут 8с: при сбое вызывающий код откатывается на локальный конвейер.
     */
    suspend fun prepareFrame(newLines: List<String>, prevLines: List<String>, advice: String? = null): List<PreparedLine>? {
        if (newLines.isEmpty()) return emptyList()
        val prevBlock = if (prevLines.isEmpty()) {
            "(прошлый кадр пуст)"
        } else {
            prevLines.takeLast(20).joinToString("\n") { "- ${it.take(90)}" }
        }
        val newBlock = newLines.mapIndexed { i, t -> "${i + 1}. ${t.take(140)}" }.joinToString("\n")
        val adviceBlock = advice?.let { "\n\nСоветы читателя (соблюдай): $it" }.orEmpty()
        val answer = kotlinx.coroutines.withTimeoutOrNull(8_000) {
            chat(
                userPrompt = "Прошлый кадр манги содержал реплики:\n$prevBlock\n\n" +
                    "Новый кадр:\n$newBlock$adviceBlock\n\n" +
                    "Для КАЖДОЙ реплики нового кадра ответь отдельной строкой строго в формате " +
                    "«N|г|текст», где N — номер, г — пол говорящего (м/ж/н), " +
                    "текст — реплика, очищенная от мусора OCR. Если реплика повторяет прошлый кадр " +
                    "(даже частично/с искажениями) — ответь «N|-». Больше НИЧЕГО не пиши.",
                systemPrompt = "Ты конвейер озвучки манги: чистишь повторы и назначаешь пол. " +
                    "Отвечаешь только строками формата N|г|текст или N|-.",
                maxTokens = 600,
            )
        } ?: return null

        val byIndex = HashMap<Int, PreparedLine>()
        for (line in answer.lines()) {
            val parts = line.trim().split('|', limit = 3)
            val n = parts.getOrNull(0)?.trim()?.toIntOrNull() ?: continue
            if (n !in 1..newLines.size) continue
            if (parts.size < 2 || parts[1].trim() == "-") {
                byIndex[n] = PreparedLine(speak = false, gender = null, text = "")
                continue
            }
            val gender = when (parts[1].trim().lowercase()) {
                "м" -> "male"
                "ж" -> "female"
                else -> null
            }
            val text = parts.getOrNull(2)?.trim().orEmpty().ifBlank { newLines[n - 1] }
            byIndex[n] = PreparedLine(speak = true, gender = gender, text = text)
        }
        if (byIndex.isEmpty()) return null // модель ответила не по протоколу
        return List(newLines.size) { i ->
            byIndex[i + 1] ?: PreparedLine(speak = true, gender = null, text = newLines[i])
        }
    }

    /**
     * Пол говорящих — СВЕРХБЫСТРЫЙ формат: модель отвечает строкой из букв,
     * по одной на реплику: «м» (мужской), «ж» (женский), «н» (не ясно).
     * Никакого JSON и рассуждений: max_tokens=40, ответ приходит за долю
     * секунды даже у reasoning-моделей. Плюс жёсткий таймаут 6с — если сеть
     * тупит, чтение продолжается нейтральным голосом, а не ждёт модель.
     * Фолбэк: локальный словарь морфологии (LocalSpeakerAi) уже отработал
     * ДО этого вызова — сюда приходят только реплики без вердикта.
     */
    suspend fun detectGendersByText(lines: List<String>): List<String?> {
        if (lines.isEmpty()) return emptyList()
        val numbered = lines.mapIndexed { i, t -> "${i + 1}) ${t.take(100)}" }.joinToString("\n")
        val answer = kotlinx.coroutines.withTimeoutOrNull(6_000) {
            chat(
                userPrompt = "Кто говорит каждую реплику? Ответь ТОЛЬКО строкой из ${lines.size} букв " +
                    "без пробелов: м=мужчина, ж=женщина, н=неясно. Пример ответа: мжнм\n\n" + numbered,
                systemPrompt = "Отвечай только буквами м/ж/н, ничего больше. Без рассуждений.",
                maxTokens = 40,
            )
        } ?: return List(lines.size) { null }

        // Берём последнюю строку ответа (reasoning-модели любят префиксы),
        // выбрасываем всё, кроме м/ж/н
        val letters = answer.lines().lastOrNull { l -> l.any { it in "мжн" } }
            ?.filter { it in "мжн" }.orEmpty()
        return List(lines.size) { i ->
            when (letters.getOrNull(i)) {
                'м' -> "male"
                'ж' -> "female"
                else -> null
            }
        }
    }
}

