package mihon.data.ocr

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat
import java.net.HttpURLConnection
import java.net.URL
import java.net.URLEncoder
import org.json.JSONArray

/**
 * Service providing instant translation for manga OCR text.
 * Supports Google Translate, DeepL, and LLM translation gateways.
 */
object MangaTranslatorService {

    /** Переводчик может расставить пробелы внутри @@@ — учитываем это. */
    private val SEPARATOR_REGEX = Regex("""\s*@\s*@\s*@\s*""")

    /**
     * Переводит СПИСОК реплик одним запросом.
     *
     * Раньше авточтение переводило по одной реплике на HTTP-запрос: на
     * странице с 15 бабблами это 15 последовательных обращений между
     * озвучками. Здесь строки склеиваются разделителем, который переводчик
     * не трогает, и режутся обратно; при несовпадении числа строк —
     * безопасный откат на построчный перевод.
     */
    suspend fun translateAll(
        texts: List<String>,
        targetLang: String = "ru",
        sourceLang: String = "auto",
    ): List<String> = withContext(Dispatchers.IO) {
        if (texts.isEmpty()) return@withContext emptyList()
        if (texts.size == 1) return@withContext listOf(translate(texts[0], targetLang, sourceLang))

        // Разделитель из символов, которые переводчик оставляет как есть.
        val separator = "\n@@@\n"
        val joined = texts.joinToString(separator)

        // У endpoint есть лимит на длину query — режем на порции.
        if (joined.length > 1500) {
            val half = texts.size / 2
            return@withContext translateAll(texts.take(half), targetLang, sourceLang) +
                translateAll(texts.drop(half), targetLang, sourceLang)
        }

        val translated = translate(joined, targetLang, sourceLang)
        val parts = translated.split(SEPARATOR_REGEX).map { it.trim() }
        if (parts.size == texts.size) {
            parts.mapIndexed { index, part -> part.ifBlank { texts[index] } }
        } else {
            logcat(LogPriority.INFO) { "Batch translate mismatch, falling back to per-line" }
            texts.map { translate(it, targetLang, sourceLang) }
        }
    }

    /**
     * Translates input text into target language (default: Russian "ru").
     */
    suspend fun translate(
        text: String,
        targetLang: String = "ru",
        sourceLang: String = "auto",
    ): String = withContext(Dispatchers.IO) {
        if (text.isBlank()) return@withContext ""

        try {
            // Instant Google Free Translate API
            val encodedText = URLEncoder.encode(text, "UTF-8")
            val urlString = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=$sourceLang&tl=$targetLang&dt=t&q=$encodedText"

            val connection = (URL(urlString).openConnection() as HttpURLConnection).apply {
                requestMethod = "GET"
                connectTimeout = 8_000
                readTimeout = 15_000
                setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
            }

            val responseText = connection.inputStream.use { it.readBytes().toString(Charsets.UTF_8) }
            val jsonArray = JSONArray(responseText)
            val sentences = jsonArray.optJSONArray(0)

            val translatedBuilder = StringBuilder()
            if (sentences != null) {
                for (i in 0 until sentences.length()) {
                    val sentence = sentences.optJSONArray(i)
                    if (sentence != null) {
                        translatedBuilder.append(sentence.optString(0, ""))
                    }
                }
            }

            connection.disconnect()
            val result = translatedBuilder.toString().trim()
            if (result.isNotBlank()) result else text
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Manga translation failed for: $text" }
            text
        }
    }
}

package mihon.data.ocr

import android.graphics.Bitmap
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import mihon.domain.ocr.model.OcrBoundingBox
import mihon.domain.ocr.model.OcrRegion
import mihon.domain.ocr.model.OcrTextOrientation
import java.io.ByteArrayOutputStream
import java.net.HttpURLConnection
import java.net.URL
import java.util.Base64
import org.json.JSONArray
import org.json.JSONObject

internal class ZenFreeOcrEngine : OcrEngine {
    override suspend fun recognizeText(image: Bitmap): String = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        recognizePage(image).joinToString("\n") { it.text }
    }

    suspend fun recognizePage(image: Bitmap): List<OcrRegion> = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val connection = URL(ENDPOINT).openConnection() as HttpURLConnection
        try {
            val payload = JSONObject().apply {
                put("model", MODEL)
                put("max_tokens", MAX_TOKENS)
                put("stream", false)
                put(
                    "messages",
                    JSONArray().put(
                        JSONObject().apply {
                            put("role", "user")
                            put(
                                "content",
                                JSONArray()
                                    .put(
                                        JSONObject().apply {
                                            put("type", "text")
                                            put("text", OCR_PROMPT)
                                        },
                                    )
                                    .put(
                                        JSONObject().apply {
                                            put("type", "image_url")
                                            put(
                                                "image_url",
                                                JSONObject().apply {
                                                    put("url", "data:image/jpeg;base64,${encodeBitmap(image)}")
                                                },
                                            )
                                        },
                                    ),
                            )
                        },
                    ),
                )
            }
            connection.requestMethod = "POST"
            connection.doOutput = true
            connection.connectTimeout = CONNECT_TIMEOUT_MS
            connection.readTimeout = READ_TIMEOUT_MS
            connection.setRequestProperty("Content-Type", "application/json")
            connection.setRequestProperty("Accept", "application/json")
            connection.outputStream.use { output ->
                output.write(payload.toString().toByteArray(Charsets.UTF_8))
            }

            val status = connection.responseCode
            val response = (if (status in 200..299) connection.inputStream else connection.errorStream)
                ?.bufferedReader()
                ?.use { it.readText() }
                .orEmpty()
            if (status !in 200..299) {
                throw IllegalStateException("OpenCode Zen OCR request failed HTTP $status")
            }

            val message = JSONObject(response)
                .optJSONArray("choices")
                ?.optJSONObject(0)
                ?.optJSONObject("message")
                ?: throw IllegalStateException("OpenCode Zen OCR response has no choices")
            parseZenOcrRegions(extractMessageContent(message))
        } finally {
            connection.disconnect()
        }
    }

    /**
     * Произвольный вопрос о странице той же vision-моделью.
     *
     * Запрос уходит тем же прямым соединением, что и OCR (решение владельца
     * проекта — без прокси-абстракции), но вместо JSON с боксами модель
     * отвечает обычным текстом. Это «глаза» агента-оркестратора: он видит
     * кадр и продолжает свой цикл с web/file-инструментами.
     */
    suspend fun askAboutPage(image: Bitmap, question: String): String? = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val prompt = question.trim()
        if (prompt.isEmpty()) return@withContext null
        val payload = JSONObject().apply {
            put("model", MODEL)
            put("max_tokens", ASK_MAX_TOKENS)
            put("stream", false)
            put(
                "messages",
                JSONArray().put(
                    JSONObject().apply {
                        put("role", "user")
                        put(
                            "content",
                            JSONArray()
                                .put(
                                    JSONObject().apply {
                                        put("type", "text")
                                        put("text", ASK_PROMPT)
                                    },
                                )
                                .put(
                                    JSONObject().apply {
                                        put("type", "image_url")
                                        put(
                                            "image_url",
                                            JSONObject().apply {
                                                put("url", "data:image/jpeg;base64,${encodeBitmap(image)}")
                                            },
                                        )
                                    },
                                ),
                        )
                    },
                ),
            )
        }
        val answer = postAndReadText(payload)
        answer?.trim()?.takeIf { it.isNotEmpty() && !it.contains("FreeTierError") }
    }

    /** POST с готовым payload и чтение строкового ответа. null при сетевой ошибке. */
    private fun postAndReadText(payload: JSONObject): String? {
        val connection = URL(ENDPOINT).openConnection() as HttpURLConnection
        return try {
            connection.requestMethod = "POST"
            connection.doOutput = true
            connection.connectTimeout = CONNECT_TIMEOUT_MS
            connection.readTimeout = READ_TIMEOUT_MS
            connection.setRequestProperty("Content-Type", "application/json")
            connection.setRequestProperty("Accept", "application/json")
            connection.outputStream.use { it.write(payload.toString().toByteArray(Charsets.UTF_8)) }
            val status = connection.responseCode
            val body = (if (status in 200..299) connection.inputStream else connection.errorStream)
                ?.bufferedReader()
                ?.use { it.readText() }
                .orEmpty()
            if (status !in 200..299) {
                // Free tier закрыт для стороннего клиента — это не повод
                // ронять разговор, агент просто продолжит без взгляда.
                null
            } else {
                extractMessageContent(JSONObject(body).optJSONArray("choices")?.optJSONObject(0)
                    ?.optJSONObject("message") ?: JSONObject())
            }
        } catch (e: Exception) {
            null
        } finally {
            connection.disconnect()
        }
    }

    override fun close() = Unit

    private fun extractMessageContent(message: JSONObject): String {
        return when (val content = message.opt("content")) {
            is String -> content
            is JSONArray -> buildString {
                for (index in 0 until content.length()) {
                    val text = content.optJSONObject(index)?.optString("text").orEmpty()
                    if (text.isNotBlank()) append(text)
                }
            }
            else -> ""
        }
    }

    private fun encodeBitmap(bitmap: Bitmap): String {
        val maxSide = maxOf(bitmap.width, bitmap.height)
        val scale = if (maxSide > MAX_IMAGE_SIDE) MAX_IMAGE_SIDE.toFloat() / maxSide else 1f
        val scaled = if (scale < 1f) {
            Bitmap.createScaledBitmap(
                bitmap,
                (bitmap.width * scale).toInt().coerceAtLeast(1),
                (bitmap.height * scale).toInt().coerceAtLeast(1),
                true,
            )
        } else {
            null
        }
        val output = ByteArrayOutputStream()
        try {
            (scaled ?: bitmap).compress(Bitmap.CompressFormat.JPEG, JPEG_QUALITY, output)
        } finally {
            if (scaled != null && !scaled.isRecycled) scaled.recycle()
        }
        return Base64.getEncoder().encodeToString(output.toByteArray())
    }

    companion object {
        const val MODEL = "space-bunny-free"
        private const val ENDPOINT = "https://opencode.ai/zen/v1/chat/completions"
        private const val MAX_IMAGE_SIDE = 1080
        private const val JPEG_QUALITY = 78
        private const val MAX_TOKENS = 4096
        private const val ASK_MAX_TOKENS = 1024
        private const val CONNECT_TIMEOUT_MS = 15_000
        private const val READ_TIMEOUT_MS = 90_000
        private val ASK_PROMPT =
            "You are the eyes of a reading assistant. Look at this page image and answer the question " +
                "about it. Describe only what is actually visible: characters, actions, panel layout, " +
                "art style, and the text you can read. If the question needs context that is not on the " +
                "image, say so plainly instead of inventing it. Answer in the language of the question. " +
                "Be concise, plain text, no JSON and no markdown."
        private val OCR_PROMPT =
            "Transcribe every visible text block in this image. Preserve the original reading order, " +
                "language, spelling, punctuation, and line breaks. Do not translate, explain, or invent text. " +
                "Return only JSON: {\"regions\":[{\"text\":\"...\",\"box\":[left,top,right,bottom]," +
                "\"orientation\":\"horizontal\"}]}. Coordinates are integers from 0 to 1000 relative to the " +
                "full image. Use one region per visible speech bubble or text block. Use [] when no text exists."
    }
}

private val zenFreeJson = Json { ignoreUnknownKeys = true }

@Serializable
private data class ZenOcrResponse(
    val regions: List<ZenOcrRegion> = emptyList(),
    val text: String = "",
)

@Serializable
private data class ZenOcrRegion(
    val text: String = "",
    val box: List<Float> = emptyList(),
    val orientation: String = "horizontal",
)

internal fun parseZenOcrRegions(content: String): List<OcrRegion> {
    if (content.isBlank()) return emptyList()
    val jsonText = content.substringAfter("```json", content).substringBefore("```").trim()
    val objectStart = jsonText.indexOf('{')
    val objectEnd = jsonText.lastIndexOf('}')
    val parsed = if (objectStart >= 0 && objectEnd > objectStart) {
        runCatching {
            zenFreeJson.decodeFromString<ZenOcrResponse>(jsonText.substring(objectStart, objectEnd + 1))
        }.getOrNull()
    } else {
        null
    }
    if (parsed == null) {
        return listOf(
            OcrRegion(
                order = 0,
                text = content.trim(),
                boundingBox = OcrBoundingBox(0f, 0f, 1f, 1f),
                textOrientation = OcrTextOrientation.Horizontal,
            ),
        )
    }

    val regions = parsed.regions.mapIndexedNotNull { index, region ->
        val text = region.text.trim()
        if (text.isBlank() || region.box.size != 4) return@mapIndexedNotNull null
        val divisor = if (region.box.all { it > 1f }) 1000f else 1f
        val left = region.box[0] / divisor
        val top = region.box[1] / divisor
        val right = region.box[2] / divisor
        val bottom = region.box[3] / divisor
        val box = OcrBoundingBox(left, top, right, bottom)
        if (!box.isValid() || left !in 0f..1f || top !in 0f..1f || right !in 0f..1f || bottom !in 0f..1f) {
            return@mapIndexedNotNull null
        }
        OcrRegion(
            order = index,
            text = text,
            boundingBox = box,
            textOrientation = if (region.orientation.equals("vertical", ignoreCase = true)) {
                OcrTextOrientation.Vertical
            } else {
                OcrTextOrientation.Horizontal
            },
        )
    }
    if (regions.isNotEmpty()) return regions
    val fallbackText = parsed.text.trim()
    return if (fallbackText.isBlank()) {
        emptyList()
    } else {
        listOf(
            OcrRegion(
                order = 0,
                text = fallbackText,
                boundingBox = OcrBoundingBox(0f, 0f, 1f, 1f),
                textOrientation = OcrTextOrientation.Horizontal,
            ),
        )
    }
}

package eu.kanade.tachiyomi.data.tts

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import org.json.JSONArray
import org.json.JSONObject
import tachiyomi.core.common.util.system.logcat
import java.net.HttpURLConnection
import java.net.URL

/**
 * Определение пола говорящего по странице: Gemini Vision получает кадр и
 * список реплик и отвечает, кто произносит каждую (male/female/unknown) —
 * по лицам персонажей и хвостикам речевых баллонов.
 *
 * Требует Google AI ключ (Настройки → OCR). Без ключа/при ошибке возвращает
 * unknown для всех реплик — озвучка идёт основным голосом, ничего не ломается.
 */
object SpeakerGenderService {

    suspend fun detect(
        imageJpeg: ByteArray,
        lines: List<String>,
        prefs: OcrPreferences,
    ): List<String?> = withContext(Dispatchers.IO) {
        val unknown = List<String?>(lines.size) { null }
        val apiKey = prefs.googleApiKey().get()
        if (apiKey.isBlank() || lines.isEmpty()) return@withContext unknown

        try {
            val model = prefs.googleModel().get().ifBlank { "gemini-2.5-flash" }
            val numbered = lines.mapIndexed { i, t -> "${i + 1}. ${t.take(120)}" }.joinToString("\n")
            val prompt =
                "This is a manga/comic page. For each numbered dialogue line below, look at the " +
                    "characters' faces and the speech bubble tails to decide WHO SPEAKS it. " +
                    "Answer ONLY with a JSON array of strings, one per line, in the same order, " +
                    "each being exactly \"male\", \"female\" or \"unknown\". No other text.\n\n" + numbered

            val body = JSONObject().apply {
                put("generationConfig", JSONObject().put("temperature", 0.0))
                put(
                    "contents",
                    JSONArray().put(
                        JSONObject().put(
                            "parts",
                            JSONArray()
                                .put(JSONObject().put("text", prompt))
                                .put(
                                    JSONObject().put(
                                        "inline_data",
                                        JSONObject()
                                            .put("mime_type", "image/jpeg")
                                            .put(
                                                "data",
                                                android.util.Base64.encodeToString(
                                                    imageJpeg,
                                                    android.util.Base64.NO_WRAP,
                                                ),
                                            ),
                                    ),
                                ),
                        ),
                    ),
                )
            }

            val url = "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$apiKey"
            val conn = (URL(url).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                doOutput = true
                connectTimeout = 15_000
                readTimeout = 45_000
                setRequestProperty("Content-Type", "application/json")
            }
            val response = try {
                conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
                val code = conn.responseCode
                val text = (if (code in 200..299) conn.inputStream else conn.errorStream)
                    ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
                if (code !in 200..299) {
                    logcat(LogPriority.WARN) { "Gender detect HTTP $code: ${text.take(120)}" }
                    return@withContext unknown
                }
                text
            } finally {
                conn.disconnect()
            }

            val answer = JSONObject(response)
                .optJSONArray("candidates")?.optJSONObject(0)
                ?.optJSONObject("content")?.optJSONArray("parts")
                ?.optJSONObject(0)?.optString("text").orEmpty()
                .replace("```json", "").replace("```", "").trim()

            val arr = JSONArray(answer)
            List(lines.size) { i ->
                when (arr.optString(i, "unknown").lowercase()) {
                    "male" -> "male"
                    "female" -> "female"
                    else -> null
                }
            }
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Speaker gender detection failed" }
            unknown
        }
    }
}

package eu.kanade.tachiyomi.data.tts

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import org.json.JSONArray
import org.json.JSONObject
import tachiyomi.core.common.util.system.logcat
import java.net.HttpURLConnection
import java.net.URL

/**
 * Проверка страницы моделью с картинкой: кто говорит каждую реплику, что
 * пропущено, где OCR ошибся.
 *
 * Локальный OCR различает ТЕКСТ, но не понимает РИСУНОК: хвостик облачка,
 * кому он указывает, где мысль, а где реплика. Поэтому голоса в сцене без
 * подписей назначаются по кругу. Единственный источник этой информации —
 * модель, которая видит картинку.
 *
 * Чего вызов НЕ делает:
 *  • не выдумывает текст: непрочитанное остаётся как есть, спорное помечается
 *    флагом [LineCheck.uncertain] — иначе получаются правдоподобные
 *    «разiiiнение» и «сахар-самаар», уже зафиксированные в todo.md;
 *  • не трогает ничего вне книги: ответ приходит страницей, применяется
 *    страницей, книжные роли пишутся в словарь этой книги.
 *
 * Без ключа/при ошибке возвращает null, и вызывающая сторона оставляет
 * локальный разбор: озвучка и порядок чтения не ломаются.
 */
object PageRoleVerifier {

    /**
     * Реплика после проверки.
     *
     * [kept] = false — модель решила, что это не реплика (титул, примечание
     * переводчика, пустая рамка). Такие строки не произносятся, но остаются в
     * отчёте, чтобы ничего не пропало молча.
     */
    data class LineCheck(
        val role: String,
        val text: String,
        val thought: Boolean,
        val kept: Boolean,
        /** true — модель не уверена; строка принимается, но помечается. */
        val uncertain: Boolean,
    )

    data class PageCheck(
        val lines: List<LineCheck>,
        /** Что страница не учла: титры, примечания, звуки. Только для отчёта. */
        val dropped: List<String>,
        /** Модель отвечает по картинке (false — вызова не было). */
        val checked: Boolean,
        /** Причина отказа, если [checked] = false. */
        val reason: String?,
    )

    /** Ответ без проверки: локальный разбор остаётся как есть. */
    fun unavailable(reason: String): PageCheck =
        PageCheck(lines = emptyList(), dropped = emptyList(), checked = false, reason = reason)

    suspend fun verify(
        imageJpeg: ByteArray,
        pageName: String,
        draftLines: List<String>,
        prefs: OcrPreferences,
    ): PageCheck = withContext(Dispatchers.IO) {
        if (draftLines.isEmpty()) return@withContext unavailable("нет строк для проверки")
        val apiKey = prefs.googleApiKey().get()
        if (apiKey.isBlank()) return@withContext unavailable("нет ключа Google AI")

        try {
            val model = prefs.googleModel().get().ifBlank { "gemini-2.5-flash" }
            val body = JSONObject().apply {
                put("generationConfig", JSONObject().put("temperature", 0.0))
                put(
                    "contents",
                    JSONArray().put(
                        JSONObject().put(
                            "parts",
                            JSONArray()
                                .put(JSONObject().put("text", prompt(pageName, draftLines)))
                                .put(
                                    JSONObject().put(
                                        "inline_data",
                                        JSONObject()
                                            .put("mime_type", "image/jpeg")
                                            .put(
                                                "data",
                                                android.util.Base64.encodeToString(
                                                    imageJpeg,
                                                    android.util.Base64.NO_WRAP,
                                                ),
                                            ),
                                    ),
                                ),
                        ),
                    ),
                )
            }

            val url = "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$apiKey"
            val conn = (URL(url).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                doOutput = true
                connectTimeout = 15_000
                readTimeout = 60_000
                setRequestProperty("Content-Type", "application/json")
            }
            val response = try {
                conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
                val code = conn.responseCode
                val text = (if (code in 200..299) conn.inputStream else conn.errorStream)
                    ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
                if (code !in 200..299) {
                    logcat(LogPriority.WARN) { "Page verify HTTP $code: ${text.take(160)}" }
                    return@withContext unavailable("HTTP $code от модели")
                }
                text
            } finally {
                conn.disconnect()
            }

            val answer = JSONObject(response)
                .optJSONArray("candidates")?.optJSONObject(0)
                ?.optJSONObject("content")?.optJSONArray("parts")
                ?.optJSONObject(0)?.optString("text").orEmpty()
            parse(answer, draftLines)
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Page role verification failed" }
            unavailable("ошибка: ${e.javaClass.simpleName}")
        }
    }

    /**
     * Разбор ответа модели.
     *
     * Модель отдаёт `{"pages":[{"page":"…","lines":[…]}]}`. Разбор терпимый к
     * мусору и Markdown-заборам: если что-то не распозналось, возвращается
     * `checked = false`, а НЕ частичный правдоподобный результат — иначе
     * половина реплик получила бы роли, а половина осталась бы с догадками
     * локального разбора, и отладить это было бы невозможно.
     */
    internal fun parse(answer: String, draftLines: List<String>): PageCheck {
        val cleaned = answer.replace("```json", "").replace("```", "").trim()
        if (cleaned.isEmpty()) return unavailable("пустой ответ модели")

        // Разбор без org.json: в юнит-тестах app-модуля он не замокан и
        // бросает, а проверять разбор модели нужно именно тестами. Свой
        // разбор уже есть в VoiceJson — он же умеет вложенные массивы.
        val pagesText = VoiceJson.extractArray(cleaned, "pages") ?: return unavailable("ответ без поля pages")
        val page = VoiceJson.parseObjects(pagesText).firstOrNull() ?: return unavailable("пустой pages")
        val linesText = VoiceJson.extractArray(page["lines"].orEmpty(), "lines")
            ?: page["lines"]?.takeIf { it.trim().startsWith("[") }
            ?: return unavailable("ответ без lines")

        val lineObjects = VoiceJson.parseObjects(linesText)
        if (lineObjects.isEmpty()) return unavailable("модель не вернула ни одной реплики")

        val out = ArrayList<LineCheck>(lineObjects.size)
        for (o in lineObjects) {
            val text = o["text"].orEmpty().trim()
            if (text.isEmpty()) continue
            // Честность важнее правдоподобия: модель не должна «улучшать» текст.
            val replaced = o["draft_text"].orEmpty().trim()
            out += LineCheck(
                role = o["role"].orEmpty().trim().ifEmpty { UNKNOWN_ROLE },
                text = text,
                thought = o["thought"].equals("true", ignoreCase = true),
                kept = o["kept"]?.equals("false", ignoreCase = true) != true,
                // Строка, которой в черновике не было, — её модель либо
                // прочитала лучше OCR, либо сочинила. Помечаем как спорную,
                // чтобы её можно было откатить, не выбрасывая страницу.
                uncertain = replaced.isNotEmpty() && replaced != text,
            )
        }

        // "dropped" лежит на уровне страницы, рядом с "lines": то, что модель
        // не считала репликой (титры, примечания, звуки). Возвращается
        // списком, чтобы пропажу нельзя было спутать с опечаткой модели.
        val dropped = page["dropped"]
            ?.let { VoiceJson.extractArray(it, "dropped") ?: it }
            ?.let { VoiceJson.parseArrayTokens(it) }
            ?.map { it.trim() }
            ?.filter { it.isNotEmpty() }
            .orEmpty()

        if (out.isEmpty()) return unavailable("все строки ответа пустые")
        return PageCheck(lines = out, dropped = dropped, checked = true, reason = null)
    }

    /** Роль, когда модель не назвала говорящего. */
    const val UNKNOWN_ROLE = "?"

    /**
     * Промпт.
     *
     * Написан так, чтобы работать на любом жанре и стиле: правила про формы
     * реплик, а не про конкретную мангу. Отдельно вынесено то, что в прошлых
     * правках приводило к выдуманным словам: модели запрещено «улучшать»
     * текст, непрочитанное помечается, а пропуск фиксируется в `dropped`,
     * чтобы его нельзя было спутать с опечаткой модели.
     */
    internal fun prompt(pageName: String, draftLines: List<String>): String {
        val numbered = draftLines.mapIndexed { i, t -> "${i + 1}. ${t.take(200)}" }.joinToString("\n")
        return """
            Ты проверяешь страницу манги/комикса/веб-комикса по КАРТИНКЕ.
            Жанр, стиль и язык любые — правила ниже универсальны.

            ЧЕРНОВИК РАСПОЗНАВАНИЯ (строки уже извлечены OCR, они могут быть
            ошибочны, склеены или обрезаны):

            $numbered

            ВЫПОЛНИ ЧЕТЫРЕ ПРОВЕРКИ:

            1) АТРИБУЦИЯ. У каждого речевого облачка есть хвостик, он указывает
               на говорящего. Определи, КТО говорит, и запиши его имя (или
               "?" если персонаж без подписи и определить нельзя).
               ФОРМЫ РЕПЛИК:
               - прямоугольная надпись ВНЕ облачков = нарратор (роль "narrator");
               - обычный эллипс/скруглённая рамка с хвостиком = речь;
               - эллипс БЕЗ хвостика (облачко мысли) = thought: true;
               - рваная/взрывная рамка, капля, шип = выкрик, это речь, а не мысль;
               - прямоугольник с прямой репликой без хвостика = тоже речь.
               Если в сцене один персонаж — у всех его реплик одна и та же роль.

            2) ПОЛНОТА. Добавь реплики, мысли и тексты рамок, которых НЕТ в
               черновике (OCR их пропустил). Для добавленных строк укажи
               draft_text = "" (их не было в черновике).
               НЕ добавляй: SFX/звуки, титулы, примечания переводчика, рамки
               без слов, подписи «глава N», Credits.

            3) ТОЧНОСТЬ ТЕКСТА. Исправь явные ошибки распознавания.
               ЖЁСТКОЕ ОГРАНИЧЕНИЕ: не додумывай, не пересказывай, не
               фразеологизмруй и не исправляй орфографию ради красоты.
               Если слово неразборчиво — оставь как распознано, лучше с
               вопросительным знаком. Выдуманное слово хуже опечатки.

            4) НЕ ЛИШНЕЕ. То, что не реплика, перенеси в "dropped" списком
               строками, а не удаляй молча.

            "page" — ровно "$pageName" (не выдумывай имя файла).
            "role" для персонажа — его имя как в сцене, для нарратора
            "narrator", для неизвестного "?".

            ВЕРНИ ТОЛЬКО JSON, без пояснений и без Markdown-заборов:
            {"pages":[{"page":"$pageName","lines":[{"role":"...","text":"...","thought":false,"kept":true}],"dropped":["..."]}]}
            Для добавленных OCR строк добавь поле "draft_text".
        """.trimIndent()
    }
}

package eu.kanade.tachiyomi.data.ocr

import android.graphics.Bitmap
import eu.kanade.tachiyomi.data.tts.PageRoleVerifier
import eu.kanade.tachiyomi.data.tts.VoiceRole
import eu.kanade.tachiyomi.data.tts.VoiceRoleDictionary
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.io.ByteArrayOutputStream

/**
 * Проверка страниц главы моделью с картинкой — вне читалки, где время не
 * ограничено.
 *
 * Внутри читалки важнее скорость, поэтому там атрибуция остаётся локальной.
 * Здесь, при подготовке главы, для каждой страницы выполняется один запрос к
 * модели: кто говорит, что пропущено, где OCR ошибся. Результат — словарь
 * ролей **этой книги**: голос персонажа работает в ней и не утекает в другие.
 *
 * Прогресс честный: [onStage] сообщает, что именно происходит сейчас
 * (OCR или ИИ), потому что запрос к модели на страницу занимает секунды и
 * без индикации выглядит как зависание.
 */
class OcrChapterAiVerifier(
    private val prefs: OcrPreferences,
) {

    /** Что сейчас делает скан — для индикации в диалоге. */
    data class Stage(
        val pageIndex: Int,
        val totalPages: Int,
        val phase: Phase,
        val detail: String,
    )

    enum class Phase {
        /** Идёт распознавание страницы локально. */
        OCR,

        /** Модель смотрит на страницу. */
        AI,

        /** Скан завершён, роли записаны. */
        DONE,
    }

    /** Счётчик страниц, на которых ИИ что-то изменил. */
    data class Summary(
        val pagesChecked: Int,
        val pagesChanged: Int,
        val rolesFound: Int,
        val skippedReason: String?,
    )

    suspend fun verifyPage(
        pageName: String,
        bitmap: Bitmap,
        regions: List<mihon.domain.ocr.model.OcrRegion>,
        onStage: (Phase, String) -> Unit = { _, _ -> },
    ): List<mihon.domain.ocr.model.OcrRegion>? {
        val ordered = regions.sortedBy { it.order }
        val draft = ordered.map { it.text.trim() }.filter { it.isNotEmpty() }
        if (draft.isEmpty()) return null
        val jpeg = encodeJpeg(bitmap) ?: return null
        val check = PageRoleVerifier.verify(jpeg, pageName, draft, prefs)
        if (!check.checked) {
            // Модель не ответила или ответила мусором: страница остаётся
            // локальной. Иначе половина страницы была бы догадкой модели, а
            // половина — распознаванием, и отладить это было бы невозможно.
            onStage(Phase.OCR, "ИИ не ответил (${check.reason ?: "неизвестно"}) — беру локальный разбор")
            return null
        }
        collectRoles(check, onStage)
        return applyToRegions(check, ordered)
    }

    /**
     * Проверенный текст возвращается в страницу.
     *
     * Что можно сделать честно:
     *  • исправить текст региона, когда модель вернула строку из черновика с
     *    другим написанием (это настоящая правка OCR);
     *  • убрать регион, который модель признала не репликой (титул, примечание) —
     *    читать его нечего.
     *
     * Чего НЕ делаем: строки, которых не было в черновике, не добавляем. У них
     * нет рамки, а выдуманная рамка означала бы подсветку и тап в пустоте.
     * Такие строки остаются в отчёте как dropped/uncertain.
     */
    /**
     * Накопитель ролей главы.
     *
     * Имена собираются по страницам и пишутся в словарь книги один раз в
     * конце: переписывать словарь на каждой странице означало бы N записей в
     * настройки и риск потерять предыдущие страницы при обрыве связи.
     */
    private val collected = LinkedHashMap<String, RoleDraft>()

    private fun collectRoles(
        check: PageRoleVerifier.PageCheck,
        onStage: (Phase, String) -> Unit,
    ) {
        check.lines.forEach { line ->
            if (!line.kept) return@forEach
            val role = line.role.trim()
            // "?" — модель не смогла определить говорящего, а "narrator" —
            // внеэкранный текст: у narrator нет голоса персонажа.
            if (role.isEmpty() || role == PageRoleVerifier.UNKNOWN_ROLE || role.equals("narrator", true)) {
                return@forEach
            }
            val key = role.lowercase()
            val draftEntry = collected.getOrPut(key) { RoleDraft(role) }
            draftEntry.pages++
            if (draftEntry.text.isBlank()) draftEntry.text = line.text
        }
        onStage(Phase.AI, "найдено персонажей ${collected.size}, не-реплик ${check.dropped.size}")
    }

    private data class RoleDraft(val name: String) {
        var pages: Int = 0
        var text: String = ""
    }

    /**
     * Записать собранные роли в словарь книги.
     *
     * Голос НЕ назначается здесь: системный TTS не умеет создавать голоса, и
     * без проверки доступности движок молча ушёл бы на другой. Имя и пол —
     * это то, что реально можно записать; конкретный голос выбирается движком
     * по полу через VoicePlugins.planAiVoice либо вручную.
     */
    fun commit(bookId: Long): Summary {
        if (bookId <= 0L || collected.isEmpty()) {
            return Summary(0, 0, collected.size, "ролей не найдено")
        }
        val existing = VoiceRoleDictionary.parseBookRoles(
            prefs.voiceRolesByBook().get(),
            bookId,
        )
        val roles = collected.values.map { draft ->
            VoiceRole(
                id = draft.name.lowercase(),
                name = draft.name,
                // Пол модели здесь не приходит: определение пола по лицу
                // делает SpeakerGenderService, и без него честнее "auto",
                // чем выдуманное значение.
                gender = VoiceRole.GENDER_AUTO,
                age = "adult",
                voice = "",
                pitch = 1.0f,
                rate = 1.0f,
                markers = listOf(draft.name),
            )
        }
        VoiceRoleDictionary.saveForBook(prefs, bookId, mergeRoles(existing, roles))
        return Summary(
            pagesChecked = collected.size,
            pagesChanged = 0,
            rolesFound = roles.size,
            skippedReason = null,
        )
    }

    fun reset() = collected.clear()

    private fun encodeJpeg(bitmap: Bitmap): ByteArray? = runCatching {
        if (bitmap.isRecycled) return null
        val out = ByteArrayOutputStream()
        // Модели достаточно уменьшенного кадра: она ищет форму облачков, а не
        // буквы, поэтому полный размер только тратит трафик и время.
        val scaled = if (bitmap.width > MAX_JPEG_EDGE) {
            val h = bitmap.height * MAX_JPEG_EDGE / bitmap.width
            Bitmap.createScaledBitmap(bitmap, MAX_JPEG_EDGE, h, true)
        } else {
            bitmap
        }
        scaled.compress(Bitmap.CompressFormat.JPEG, JPEG_QUALITY, out)
        if (scaled !== bitmap && !scaled.isRecycled) scaled.recycle()
        out.toByteArray().takeIf { it.isNotEmpty() }
    }.onFailure { logcat(LogPriority.WARN, it) { "Chapter AI jpeg encode failed" } }.getOrNull()

    companion object {
        /**
         * Правило слияния: ручная настройка главнее модели.
         *
         * Раньше здесь отбрасывалась роль с тем же именем и писалась роль от
         * модели с ПУСТЫМ voice — то есть голос, который читатель назначил
         * руками, стирался на каждом скане главы. Теперь для имени с ручным
         * голосом сохраняется ручная роль, а модель добавляет только новые
         * имена.
         */
        fun mergeRoles(
            existing: List<VoiceRole>,
            fromAi: List<VoiceRole>,
        ): List<VoiceRole> {
            val manualNames = existing.filter { it.voice.isNotBlank() }
                .map { it.name.lowercase() }
                .toSet()
            val manual = existing.filter { it.voice.isNotBlank() }
            return manual + fromAi.filter { r -> r.name.lowercase() !in manualNames }
        }

        /**
         * Чистая функция: проверка страницы -> новые регионы.
         *
         * Объект-обёртка не нужен и состояния не касается, поэтому вынесена в
         * companion: её проверяют тесты без Android и без Injekt.
         */
        fun applyToRegions(
        check: PageRoleVerifier.PageCheck,
        ordered: List<mihon.domain.ocr.model.OcrRegion>,
    ): List<mihon.domain.ocr.model.OcrRegion>? {
        val byText = check.lines
            .filter { it.kept && !it.uncertain }
            .associateBy { normalize(it.text) }
        val corrected = ordered.mapNotNull { region ->
            val fixed = byText[normalize(region.text)]?.text
            when {
                // Модель признала это не репликой — регион уходит из чтения.
                check.lines.any { !it.kept && normalize(it.text) == normalize(region.text) } -> null
                fixed != null && fixed != region.text -> region.copy(text = fixed)
                else -> region
            }
        }
        if (corrected.size == ordered.size && corrected.zip(ordered).all { (a, b) -> a.text == b.text }) {
            return null // ничего не изменилось — кэш не трогаем зря
        }
        return corrected.mapIndexed { i, r -> r.copy(order = i) }
    }

    private fun normalize(text: String): String =
        text.lowercase().filter { it.isLetterOrDigit() }


        private const val MAX_JPEG_EDGE = 1024
        private const val JPEG_QUALITY = 80
    }
}

package mihon.data.ocr

import android.content.Context
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat
import java.io.File

/**
 * Журналы авточтения и сканирования для экрана истории — продвинутая версия.
 *
 * Что изменилось по запросу:
 *  - История сканирования — была in-memory (терялась при перезапуске), теперь
 *    персистентная: JSON на диске + StateFlow, лимит 500, survive reboot
 *  - Автоочистка по времени (30 дней) и по размеру
 *  - Экспорт/импорт истории через workspace/history/
 *  - Потоковый апдейт: пока OCR идёт по тайлам, запись обновляется,
 *    а не только в конце
 *  - Фильтры по успеху/дате в UI (через `filteredScans(okOnly)`)
 *  - Сохраняются и стрим-события (partial), чтобы видеть прогресс
 */
object OcrHistoryStore {

    private const val MAX_ENTRIES = 500
    private const val FILE_NAME = "ocr_history.json"
    private const val RETENTION_MS = 30L * 24 * 60 * 60 * 1000 // 30 дней

    @Serializable
    data class ScanEntry(
        val time: Long,
        val ok: Boolean,
        val detail: String,
        val wordDictHits: Int = 0,
        val punctFixes: Int = 0,
        val splitFixes: Int = 0,
        val isStreaming: Boolean = false,
        val page: String = "",
    )

    @Serializable
    data class AutoReadEntry(
        val time: Long,
        val ok: Boolean,
        val event: String,
        val detail: String,
        val voice: String = "",
        val durationMs: Long = 0,
    )

    @Serializable
    private data class Persisted(
        val scans: List<ScanEntry> = emptyList(),
        val reads: List<AutoReadEntry> = emptyList(),
    )

    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true; prettyPrint = false }

    private val _scans = MutableStateFlow<List<ScanEntry>>(emptyList())
    val scans: StateFlow<List<ScanEntry>> = _scans

    private val _reads = MutableStateFlow<List<AutoReadEntry>>(emptyList())
    val reads: StateFlow<List<AutoReadEntry>> = _reads

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private var persistFile: File? = null
    private var initialized = false

    fun init(context: Context) {
        if (initialized) return
        initialized = true
        val file = File(context.filesDir, FILE_NAME)
        persistFile = file
        scope.launch {
            runCatching {
                if (file.exists()) {
                    val raw = file.readText()
                    val data = json.decodeFromString<Persisted>(raw)
                    val cutoff = System.currentTimeMillis() - RETENTION_MS
                    _scans.value = data.scans.filter { it.time >= cutoff }.take(MAX_ENTRIES)
                    _reads.value = data.reads.filter { it.time >= cutoff }.take(MAX_ENTRIES)
                }
            }.onFailure { e -> logcat(LogPriority.WARN, e) { "OcrHistoryStore load failed" } }
        }
    }

    private fun persist() {
        val file = persistFile ?: return
        scope.launch {
            runCatching {
                val data = Persisted(_scans.value.take(MAX_ENTRIES), _reads.value.take(MAX_ENTRIES))
                file.writeText(json.encodeToString(data))
            }.onFailure { e -> logcat(LogPriority.WARN, e) { "OcrHistoryStore persist failed" } }
        }
    }

    @Synchronized
    fun addScan(
        ok: Boolean,
        detail: String,
        wordDictHits: Int = 0,
        punctFixes: Int = 0,
        splitFixes: Int = 0,
        isStreaming: Boolean = false,
        page: String = "",
    ) {
        val entry = ScanEntry(
            System.currentTimeMillis(), ok, detail, wordDictHits, punctFixes, splitFixes, isStreaming, page,
        )
        _scans.value = (listOf(entry) + _scans.value).take(MAX_ENTRIES)
        persist()
    }

    @Synchronized
    fun addStreamingScan(partialDetail: String, page: String = "") {
        addScan(ok = true, detail = partialDetail, isStreaming = true, page = page)
    }

    @Synchronized
    fun addAutoRead(ok: Boolean, event: String, detail: String, voice: String = "", durationMs: Long = 0) {
        val entry = AutoReadEntry(System.currentTimeMillis(), ok, event, detail, voice, durationMs)
        _reads.value = (listOf(entry) + _reads.value).take(MAX_ENTRIES)
        persist()
    }

    // Legacy overload for existing call sites
    @Synchronized
    fun addAutoRead(ok: Boolean, event: String, detail: String) {
        addAutoRead(ok, event, detail, voice = "", durationMs = 0)
    }

    @Synchronized
    fun addScan(ok: Boolean, detail: String, wordDictHits: Int, punctFixes: Int, splitFixes: Int) {
        addScan(ok, detail, wordDictHits, punctFixes, splitFixes, isStreaming = false, page = "")
    }

    fun filteredScans(okOnly: Boolean = false, query: String = ""): List<ScanEntry> {
        var list = _scans.value
        if (okOnly) list = list.filter { it.ok }
        if (query.isNotBlank()) {
            val q = query.lowercase()
            list = list.filter { it.detail.lowercase().contains(q) || it.page.lowercase().contains(q) }
        }
        return list
    }

    fun filteredReads(query: String = ""): List<AutoReadEntry> {
        if (query.isBlank()) return _reads.value
        val q = query.lowercase()
        return _reads.value.filter { it.event.lowercase().contains(q) || it.detail.lowercase().contains(q) }
    }

    @Synchronized
    fun clearAll() {
        _scans.value = emptyList()
        _reads.value = emptyList()
        persist()
    }

    @Synchronized
    fun clearScans() {
        _scans.value = emptyList()
        persist()
    }

    @Synchronized
    fun clearReads() {
        _reads.value = emptyList()
        persist()
    }

    fun export(context: Context): File? {
        return try {
            val dir = File(context.getExternalFilesDir(null), "history").apply { mkdirs() }
            val out = File(dir, "ocr_history_${System.currentTimeMillis()}.json")
            val data = Persisted(_scans.value, _reads.value)
            out.writeText(json.encodeToString(data))
            out
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "OcrHistoryStore export failed" }
            null
        }
    }
}

import eu.kanade.tachiyomi.util.system.toast
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

@Composable
fun ReaderAiChatOverlay(
    context: Context,
    mangaId: Long?,
    mangaTitle: String,
    chapterTitle: String?,
    onClose: () -> Unit,
    onVoiceGender: String = "female",
    /**
     * Полная остановка по кнопке «Стоп»: прерывает ход агента и всё, что он
     * успел запустить. Без этого кнопка «Стоп» в меню читалки недоступна
     * именно тогда, когда она нужнее всего, — когда открыт чат.
     */
    onStopRequested: () -> Unit = {},
) {
    val history = remember { mutableStateListOf<Msg>() }
    var loading by remember { mutableStateOf(false) }
    var input by remember { mutableStateOf("") }
    var showClearConfirm by remember { mutableStateOf(false) }
    var attachedName by remember { mutableStateOf<String?>(null) }
    var attachedBytes by remember { mutableStateOf<ByteArray?>(null) }
    var activity by remember { mutableStateOf("") }
    var elapsed by remember { mutableStateOf(0L) }
    var backendLine by remember { mutableStateOf("") }
    var sessionLine by remember { mutableStateOf("") }
    // Как работаем с этой книгой: чат/отыгрыш, 18+, цензура. Заполняется
    // из файла книги и меняется чипами прямо в шапке. Ключ — mangaId, иначе
    // при переходе на другую книгу остались бы настройки предыдущей.
    var bookSettings by remember(mangaId) {
        mutableStateOf(BookKnowledge.profile(context, mangaId))
    }
    // У отыгрыша своя история: канал определяется режимом и объявлен здесь,
    // до лямбды отправки, которая его использует.
    val historyChannel = AiHistoryManager.channelOf(bookSettings.mode)
    // Растёт после каждого ответа: эффект ниже перечитывает сводку сессии.
    var sessionRefresh by remember { mutableStateOf(0) }

    // Вкладка чата: 0 — переписка, 1 — файлы workspace. Читатель искал файлы
    // в чате и в папке телефона: папки на Android 11+ приложение создать не
    // может, поэтому список файлов показываем прямо в чате.
    var tab by remember { mutableStateOf(0) }
    var filesRefresh by remember { mutableStateOf(0) }

    val listState = rememberLazyListState()
    val scope = rememberCoroutineScope()

    // Задача текущего хода: без ссылки её нечем прервать, а прерывать
    // читателю нужно — иначе ответ агента нельзя остановить.
    var runningJob by remember { mutableStateOf<kotlinx.coroutines.Job?>(null) }

    // Сообщение, отправленное «поверх» текущего хода. Раньше поле ввода
    // блокировалось на всё время работы агента, поэтому последовательно
    // спросить его было нельзя в принципе.
    var queuedMessage by remember { mutableStateOf<Pair<String, ByteArray?>?>(null) }

    val showToast: (String) -> Unit = { message -> context.toast(message) }
    val scrollTo: (Int) -> Unit = { index -> scope.launch { listState.animateScrollToItem(index) } }
    val setActivity: (String) -> Unit = { text ->
        scope.launch {
            activity = text
            elapsed = 0L
        }
    }

    LaunchedEffect(Unit) {
        val prefs = uy.kohesive.injekt.Injekt.get<mihon.domain.ocr.service.OcrPreferences>()
        // Снимок бэкенда читает сеть, каталоги моделей и сессии ранера — это
        // диск и binder, и на главном потоке (здесь это Main.immediate)
        // он подвешивал чат на открытии.
        val state = withContext(Dispatchers.IO) {
            eu.kanade.tachiyomi.data.ai.AiBackends.state(context, prefs)
        }
        val backend = eu.kanade.tachiyomi.data.ai.AiBackends.byId(prefs.aiBackend().get())
        val status = eu.kanade.tachiyomi.data.ai.AiBackends.statusOf(
            backend,
            state,
            prefs.aiProvider().get(),
        )
        val chatTarget = eu.kanade.tachiyomi.data.ai.AiModelRoles.chatTarget(
            chatBackend = prefs.aiBackend().get(),
            chatProvider = prefs.aiProvider().get(),
            chatModel = chatModelLabel(context, prefs),
        )
        val orchestrator = eu.kanade.tachiyomi.data.ai.AiModelRoles.orchestratorTarget(
            chatBackend = prefs.aiBackend().get(),
            chatProvider = prefs.aiProvider().get(),
            chatModel = chatTarget.model,
            orchestratorBackend = prefs.aiOrchestratorBackend().get(),
            orchestratorModel = prefs.aiOrchestratorModel().get(),
            backendState = state,
        )
        val ocrEngine = prefs.ocrModel().get()
        val autoRotate = prefs.aiAutoRotate().get()
        val lines = eu.kanade.tachiyomi.data.ai.AiModelRoles.statusLines(
            eu.kanade.tachiyomi.data.ai.AiModelRoles.ocrTarget(
                engineId = ocrEngine.name,
                engineTitle = mihon.data.ocr.OcrPlugins.byModel(ocrEngine).title,
            ),
            chatTarget,
            orchestrator,
        )
        backendLine = if (status.available) {
            // При включённой автосмене отвечать может не та модель, что выбрана,
            // и без подписи это выглядит как «выбрали не ту». Имя ответившей
            // модели показывается в подвале каждого сообщения.
            val rotationNote = if (autoRotate) " · автосмена моделей" else ""
            (lines.joinToString(" · ") + rotationNote).trim()
        } else {
            "${backend.title} · недоступно: ${status.missing.joinToString(", ")}"
        }
    }

    LaunchedEffect(loading) {
        if (!loading) {
            elapsed = 0L
            activity = ""
        }
    }

    LaunchedEffect(loading) {
        while (loading) {
            kotlinx.coroutines.delay(1000)
            elapsed += 1
        }
    }

    val send: (String, String?, ByteArray?) -> Unit = { text, fileName, fileBytes ->
        if (text.isNotBlank() && !loading) {
            // Поле очищаем сразу при отправке: оставлять отправленный текст в
            // поле нельзя — читатель видит «не отправлено» и ждёт второй раз.
            input = ""
            runningJob = sendMessage(
                context = context,
                scope = scope,
                mangaId = mangaId,
                mangaTitle = mangaTitle,
                chapterTitle = chapterTitle,
                input = text,
                attachmentsName = fileName,
                attachmentsBytes = fileBytes,
                history = history,
                loading = { loading = it },
                onScroll = scrollTo,
                censorship = bookSettings.censorship,
                historyChannel = historyChannel,
                onActivity = setActivity,
                onDone = { sessionRefresh += 1 },
            ).also {
                // Ход завершился — ссылка больше не нужна, иначе «Стоп» отменил
                // бы уже завершённую работу и обнулил индикатор.
                scope.launch {
                    it.join()
                    runningJob = null
                }
            }
            attachedName = null
            attachedBytes = null
        }
    }

    // Отправка, которая не теряет сообщение, поданное во время работы
    // агента: оно встаёт в очередь и уходит следующим ходом.
    val sendOrQueue: (String, String?, ByteArray?) -> Unit = { text, fileName, fileBytes ->
        when {
            text.isBlank() -> Unit
            // Идёт ход — копим. Больше одного сообщения в очередь не берём:
            // читателю важнее ответить сейчас, чем копить пачку.
            loading -> {
                if (queuedMessage == null) {
                    queuedMessage = text to fileBytes
                    input = ""
                    attachedName = null
                    attachedBytes = null
                    showToast("Сообщение в очереди — уйдёт следом")
                }
            }
            else -> send(text, fileName, fileBytes)
        }
    }

    // Стоп: прерываем ход агента и всё, что он успел запустить, — озвучку и
    // авточтение. Иначе остановленный ответ оставляет читателя вслух
    // читающую главу.
    val stopEverything: () -> Unit = {
        runningJob?.cancel()
        runningJob = null
        loading = false
        onStopRequested()
        showToast("Остановлено")
    }

    // Очередь уходит сама, как только освободился агент.
    LaunchedEffect(loading, queuedMessage) {
        val next = queuedMessage
        if (!loading && next != null) {
            queuedMessage = null
            send(next.first, null, next.second)
        }
    }

    // История книги грузится один раз на книгу: перечитывать её на каждый
    // ответ нельзя — файл на диске ещё не дописан, и перезагрузка стирала бы
    // сообщение, которое агент только что сохранил.
    // Канал входит в ключ ОТДЕЛЬНО: раньше он был в одном ключе с mangaId, и
    // переключение «Чат ⇄ Отыгрыш» делало history.clear() прямо посреди
    // разговора — читатель видел пустой чат и делал вывод, что агент всё
    // забыл.
    LaunchedEffect(mangaId) {
        history.clear()
        history.addAll(AiHistoryManager.load(context, mangaId, historyChannel))
        runCatching { listState.scrollToItem((history.size - 1).coerceAtLeast(0)) }
    }
    LaunchedEffect(mangaId, historyChannel) {
        if (history.isEmpty()) return@LaunchedEffect
        val loaded = AiHistoryManager.load(context, mangaId, historyChannel)
        if (loaded.isEmpty()) return@LaunchedEffect
        history.clear()
        history.addAll(loaded)
        runCatching { listState.scrollToItem((history.size - 1).coerceAtLeast(0)) }
    }

    // Сводка сессии — отдельный эффект: она меняется после ответа агента,
    // когда выучены новые правила/источники.
    LaunchedEffect(mangaId, sessionRefresh) {
        // Сессия книги создаётся при первом входе в чат, чтобы знания и
        // история этой книги не смешивались с глобальным AI-чатом.
        if (mangaId != null) {
            sessionLine = withContext(Dispatchers.IO) {
                eu.kanade.tachiyomi.data.ai.BookKnowledge.ensureSession(context, mangaId)
                eu.kanade.tachiyomi.data.ai.BookKnowledge.summaryLine(context, mangaId)
            }
        } else {
            sessionLine = eu.kanade.tachiyomi.data.ai.BookKnowledge.summaryLine(context, null)
        }
    }

    val fileLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument(),
    ) { uri: Uri? ->
        if (uri == null) return@rememberLauncherForActivityResult
        val (name, bytes) = readUriFile(context, uri) ?: return@rememberLauncherForActivityResult
        attachedName = name
        attachedBytes = bytes
    }

    Dialog(
        properties = DialogProperties(
            usePlatformDefaultWidth = false,
            decorFitsSystemWindows = false,
        ),
        onDismissRequest = onClose,
    ) {
        Surface(modifier = Modifier.fillMaxSize()) {
            Column(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        // Диалог рисуется во весь экран (decorFitsSystemWindows =
                        // false), поэтому шапку и поле ввода надо прижать к
                        // системным отступам: иначе часы и заголовок наезжали
                        // друг на друга, а кнопка отправки — на жестовую
                        // полосу внизу.
                        .statusBarsPadding()
                        .padding(horizontal = 12.dp, vertical = 10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Icon(
                        Icons.Outlined.SmartToy,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(22.dp),
                    )
                    Spacer(Modifier.width(8.dp))
                    Column(Modifier.weight(1f)) {
                        Text(
                            "AI-чат · $mangaTitle",
                            style = MaterialTheme.typography.titleMedium,
                            maxLines = 1,
                        )
                        Text(
                            chapterTitle ?: "читалка",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            maxLines = 1,
                        )
                        if (backendLine.isNotBlank()) {
                            Text(
                                backendLine,
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                maxLines = 2,
                            )
                        }
                        if (sessionLine.isNotBlank()) {
                            Text(

