/**
 * Какая часть файла страницы попала в кадр, в нормализованных координатах
 * (0..1) плюс размеры самого файла.
 *
 * Размеры берём у вьюхи страницы, потому что [ReaderSelectionCapture.sourceRect]
 * — это прямоугольник в координатах ИМЕННО ЭТОГО файла (вьюха сама
 * разворачивает зум, панораму, поворот и обрезку рамок), а размеры кадра
 * после даунскейла к ним непригодны.
 *
 * null — геометрии нет: кадр склеен из нескольких страниц (экран вебтуна
 * перекрыл границу полос) или страница ещё не отрисована. Тогда запись
 * скриншота остаётся без геометрии, и в книге она просто ничего не рисует.
 */
private fun frameGeometryOf(
    captures: List<ReaderSelectionCapture>,
): AutoReadEngine.OcrFrameGeometry? {
    val capture = captures.singleOrNull() ?: return null
    val source = (capture.bitmapSource as? ReaderPageImageView)?.sourceSizeOrNull() ?: return null
    val (sourceWidth, sourceHeight) = source
    if (sourceWidth <= 0 || sourceHeight <= 0) return null
    val sourceRect = capture.sourceRect
    val crop = mihon.data.ocr.SerializableNormalizedRect(
        left = sourceRect.left.toFloat() / sourceWidth,
        top = sourceRect.top.toFloat() / sourceHeight,
        right = sourceRect.right.toFloat() / sourceWidth,
        bottom = sourceRect.bottom.toFloat() / sourceHeight,
    )
    if (!crop.isUsable()) return null
    return AutoReadEngine.OcrFrameGeometry(
        sourceWidth = sourceWidth,
        sourceHeight = sourceHeight,
        crop = crop,
        // Прокрутка страницы: сколько её высоты осталось позади кадра.
        scrollFraction = crop.top,
    )
}

private suspend fun resolveSelectionCaptures(
    rect: android.graphics.RectF,
): List<ReaderSelectionCapture> {
    val screenRect = dialogRootRectToScreenRect(rect)
    val captures = withUIContext {
        val resolvedCaptures = viewModel.state.value.viewer?.resolveSelectionCaptures(
            ReaderSelectionRegion(screenRect = screenRect),
        )
        if (!resolvedCaptures.isNullOrEmpty()) {
            exitOcrMode()
        }
        resolvedCaptures
    }
        .orEmpty()

    if (captures.isNotEmpty()) {
        logcat(LogPriority.DEBUG) {
            "Selection resolved ${captures.size} capture(s) for screenRect=" +
                "${screenRect.left},${screenRect.top},${screenRect.right},${screenRect.bottom}"
        }
    }
    return captures
}

fun showOcrResult(selection: ReaderOcrRegionSelection) {
    if (!shouldHandleCachedOcrRegionTaps()) {
        return
    }

    if (shouldOpenCachedOcrResultInPopup()) {
        if (!openCachedOcrOverlaySession(selection)) {
            return
        }
    } else {
        clearActiveOcrOverlaySession()
    }

    viewModel.showOcrResult(
        queryText = selection.queryText,
        origin = ReaderViewModel.OcrResultOrigin.CachedPageTap,
        initialSearchText = searchTextForOffset(selection.queryText, selection.initialSelectionOffset),
        source = viewModel.currentOcrSource(),
    )
}

private fun shouldOpenCachedOcrResultInPopup(): Boolean {
    return dictionaryPreferences.ocrResultPresentation().get() == OcrResultPresentation.POPUP
}

private fun openCachedOcrOverlaySession(selection: ReaderOcrRegionSelection): Boolean {
    val anchorRect = selection.anchorRectOnScreen?.let(::screenRectToDialogRootRect) ?: return false
    if (activeOcrOverlaySession?.matches(selection) == true) {
        dismissActiveOcrOverlaySession()
        return false
    }

    activeOcrOverlaySession = ActiveOcrOverlaySession(
        selection = selection,
        anchorRectInDialogRoot = anchorRect,
    )
    return syncActiveOcrOverlay()
}

fun shouldHandleCachedOcrRegionTaps(): Boolean {
    return true
}

fun hasActiveOcrOverlaySession(): Boolean {
    return activeOcrOverlaySession != null
}

    private const val READER_ACTION_PREFIX = "reader."

    /**
     * Шаг вебтуна после ПОСЛЕДНЕЙ реплики кадра в режиме «плавно пофразно».
     *
     * В этом режиме каждая реплика прокручивает себя сама, поэтому обычный
     * шаг кадра здесь равен нулю — а без шага после последней реплики цикл
     * перечитывал один экран по кругу. Шаг небольшой (как «медленно»): он не
     * перескакивает через бабл, а лишь доводит вьюпорт до следующего текста.
     */
    private const val PHRASE_FINAL_STEP = 0.15f

    /**
     * Пауза на отрисовку следующей страницы перед новым кадром OCR.
     *
     * Раньше здесь стояли фиксированные 350 + 900 мс: между страницами
     * всегда была пустота в полторы секунды, и чтение шло рывками. Теперь
     * паузу между репликами задаёт ритм голоса (см.
     * AutoReadEngine.pauseAfterLineMs), а это число оставляет только на
     * перерисовку вьювера — она идёт параллельно, а не после озвучки.
     */
    private const val PAGE_SETTLE_MS = 180L

    fun newIntent(context: Context, mangaId: Long?, chapterId: Long?): Intent {
        return Intent(context, ReaderActivity::class.java).apply {
            putExtra("manga", mangaId)
            putExtra("chapter", chapterId)
            addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)
        }
    }

    /**
     * Читалка, которая сразу начинает авточтение (для фонового скан-чтения
     * главы). Не зависит от сохранённой опции «автостарт чтения», чтобы
     * сценарий «сканируй главу → открой и читай» работал предсказуемо и
     * не менял постоянные настройки пользователя.
     */
    fun newAutoReadIntent(context: Context, mangaId: Long?, chapterId: Long?): Intent {
        return newIntent(context, mangaId, chapterId).apply {
            putExtra("autoread_start", true)
        }
    }

    fun newIntent(context: Context, uri: android.net.Uri): Intent {
        return Intent(context, ReaderActivity::class.java).apply {
            data = uri
            addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
    }
}

